// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Anadolu mutfak mirası, yöresel yemekler, coğrafi işaretli lezzetler ve içecek kültürü tarihi (kahve, çay, boza, şerbet, tarhana, zeytinyağı, pişirme kapları) (kolay).
const ozCulture15Kolay = <(String, String, List<String>, String)>[
  ('Osmanlı saray teşkilatında padişahın kahve takımını korumak, kahvesini pişirmek ve törenle sunmaktan sorumlu görevliye hangi unvan verilirdi?', 'Kahvecibaşı', ['Çaşnigirbaşı', 'Şerbetçibaşı', 'Kilercibaşı'], 'Enderun ve Birun protokolünde önemli yeri olan Kahvecibaşı, padişahın hususi kahve merasimini yöneten güvenilir saray görevlisiydi.'),
  ('Türk kahvesinin cezvede ağır ateşte pişirilip fincana aktarılmasından sonra dibe çöken ince öğütülmüş tortuya ne ad verilir?', 'Telve', ['Köpük', 'Posalı öz', 'Kavruk un'], 'Çok ince çekilen kahve çekirdekleri filtre edilmeden pişirildiği için fincanın tabanında kalan tortu telve olarak adlandırılır.'),
  ('Güneydoğu Anadolu\'da birkaç kez kaynatılıp süzülerek pekmez kıvamına getirilen, şekersiz ve kulpsuz küçük fincanlarda ikram edilen acı kahve türü hangisidir?', 'Mırra', ['Menengiç kahvesi', 'Dibek kahvesi', 'Cilveli kahve'], 'Adını Arapça \'acı\' anlamındaki murr sözcüğünden alan mırra, Urfa ve Mardin yöresinde özel protokol kurallarıyla kulpsuz fincanda sunulur.'),
  ('Kafein içermemesiyle bilinen, yabani fıstık (çitlembik) ağacının kavrulmuş meyvelerinden süt veya suyla pişirilen yöresel içecek hangisidir?', 'Menengiç kahvesi', ['Mırra kahvesi', 'Tatar kahvesi', 'Yemen moka kahvesi'], 'Gaziantep başta olmak üzere Güneydoğu ve Akdeniz dağlarında yetişen menengiç meyvesi yağlı dokusuyla kavrulup ezilerek kafeinsiz bir içecek verir.'),
  ('Kahve çekirdeklerinin metal değirmen bıçaklarıyla kesilmek yerine taş ya da ahşap çukur kaplarda tokmakla dövülerek ezilmesi hangi kahve çeşidine adını vermiştir?', 'Dibek kahvesi', ['Süvari kahvesi', 'Mırra kahvesi', 'Közde kül kahvesi'], 'Taş dibekte dövülen kahve kendi yağını dışarı bırakmadan yumuşak ve kremamsı bir doku kazanır; çoğu kez kakule gibi aromalarla harmanlanır.'),
  ('Türk kahvesi ikramında fincanın yanına bir bardak su konulmasının eski konukseverlik geleneğindeki sessiz iletişim anlamı aşağıdakilerden hangisidir?', 'Misafirin tok mu yoksa aç mı olduğunu nezaketle anlamak', ['Kahvenin yeterince taze kavrulup kavrulmadığını sınamak', 'Ev sahibinin misafire ne kadar süre ayırabileceğini bildirmek', 'İkram edilen kahvenin şeker oranını sonradan seyreltmek'], 'Geleneksel görgüde konuk önce kahveye uzanırsa tok olduğu, önce suyu içerse karnının aç olduğu anlaşılır ve hemen sofra hazırlığına girişilirdi.'),
  ('Türk kahvesi kültürü ve geleneği hangi uluslararası kuruluşun Somut Olmayan Kültürel Miras Temsili Listesi\'ne 2013 yılında kaydedilmiştir?', 'UNESCO', ['FAO', 'ICOMOS', 'UNWTO'], 'Türk kahvesi kültürü ve geleneği, sohbet ve konukseverlik boyutlarıyla 2013 yılında UNESCO İnsanlığın Somut Olmayan Kültürel Mirası listesine alınmıştır.'),
  ('Doğu Karadeniz\'de çay tarımının bilimsel temellerle başlamasını sağlayan, 1930\'ların sonunda Batum\'dan tohum getirerek Rize\'de ilk çay fidanlığını ve fabrikasını kuran ziraatçı kimdir?', 'Zihni Derin', ['Hadiye Tuncer', 'Tahsin Coşkan', 'Nazım İnebeyli'], 'Ziraat mühendisi Zihni Derin, Rize\'de kurduğu deneme bahçeleri ve yetiştirdiği fidanlarla Türkiye\'de ekonomik çay tarımının kurucusu kabul edilir.'),
  ('Erzurum ve Kars yöresinde çayın bardağa şeker atılmadan, sert küp şekerin dil ile damak arasına sıkıştırılmasıyla içilmesi yöntemine ne ad verilir?', 'Kıtlama', ['Demleme', 'Haşlama', 'Süzdürme'], 'Kıtlama usulünde özel sert kesme şekerden küçük bir parça ısırılarak ağızda tutulur ve şekersiz açık çay yudumlandıkça şeker yavaşça erir.'),
  ('Ortasından geçen dikey borusunda odun veya kömür ateşinin yandığı, çevresindeki haznede suyun kaynadığı ve tepesine demlik oturtulan geleneksel çay aracına ne denir?', 'Semaver', ['Güğüm', 'Kazan', 'İbrik'], 'Rusya ve Kafkasya üzerinden Anadolu\'ya yayılan semaver, özellikle Amasya, Tokat, Samsun ve Doğu Anadolu\'da çay kültürünün simge gerecidir.'),
  ('Darı irmiği, su ve şekerden laktik asit ile hafif alkol fermantasyonu sonucu üretilen, kış gecelerinde üzerine tarçın ve sarı leblebi konularak içilen kıvamlı içecek hangisidir?', 'Boza', ['Salep', 'Şalgam', 'Kımız'], 'Orta Asya\'dan Balkanlar\'a uzanan köklü bir geçmişe sahip olan boza, darı başta olmak üzere tahılların mayalanmasıyla hazırlanan besleyici kış içeceğidir.'),
  ('Kış aylarında sütle kaynatılarak içilen geleneksel salebin kendine özgü koyu kıvamını veren bitkisel hammadde aşağıdakilerden hangisidir?', 'Yabani orkide türlerinin kurutulup öğütülmüş toprak altı yumruları', ['Meşe ağaçlarının gövdesinden sızan reçineli zamk damlaları', 'Buğday nişastasının kavrulmuş keçiboynuzu çekirdeğiyle karışımı', 'Toros sediri kozalaklarının dövülmüş iç tohumları'], 'Salep, Orchis ve Ophrys gibi yabani orkide cinslerinin yumrularında bulunan glukomannan polisakkariti sayesinde sütü yoğunlaştırır.'),
  ('Henüz olgunlaşmamış ekşi yeşil üzümlerin sıkılmasıyla elde edilen ve Ege ile Güney Anadolu\'da hem yemeklere ekşilik vermede hem de soğuk şerbet yapımında kullanılan sıvı hangisidir?', 'Koruk suyu', ['Üzüm şırası', 'Nar ekşisi', 'Gilaburu özü'], 'Bağ bozumu öncesinde seyreltme amacıyla toplanan ham üzümler (koruk) sıkılarak ferahlatıcı koruk şerbeti yapılır.'),
  ('Orta Asya Türk topluluklarının göçebe yaşam kültüründen miras kalan ve kısrak sütünün tulumlarda çalkalanarak mayalanmasıyla elde edilen geleneksel içecek hangisidir?', 'Kımız', ['Kefir', 'Şıra', 'Sübye'], 'Dede Korkut anlatılarından itibaren Türk içecek kültürünün önemli unsurlarından olan kımız, kısrak sütünün laktik asit ve maya etkisiyle fermente edilmesiyle üretilir.'),
  ('Balıkesir\'in Susurluk ilçesiyle özdeşleşen coğrafi işaretli ayranı sıradan ayrandan ayıran en belirgin üretim ve sunum özelliği nedir?', 'Yağlı ayranın devirdaim pompalarıyla yüksekten dökülerek kalın krema köpüğü oluşturulması', ['İçerisine nane yaprağı, sarımsak ve sızma zeytinyağı eklenerek çırpılması', 'Yalnızca koyun yoğurdunun maden suyu ve buz parçalarıyla seyreltilmesi', 'Bakır kazanlarda kısık ateşte pişirilmiş süzme yoğurttan yapılması'], 'Susurluk ayranında tuz oranı düşük tam yağlı yoğurt kullanılır ve ayran dar borudan hızla kazana geri akıtılarak bardak üstünde bol kaymaksı köpük elde edilir.'),
  ('Geleneksel yayık ayranı üretilirken ahşap yayıkta yoğurdun suyla uzun süre çalkalanması sırasında yan ürün olarak yüzeyde toplanan besin maddesi nedir?', 'Tereyağı', ['Lor peyniri', 'Kaymak', 'Çökelek'], 'Yayıkta dövülen yoğurdun süt yağı zerrecikleri birleşerek tereyağı topakları halinde üste çıkar; geriye kalan ferahlatıcı sıvı ise yayık ayranıdır.'),
  ('Erzurum, Kars ve Doğu Anadolu mutfağında mor yapraklı taze fesleğen türünün sıcak suda limon tuzu veya limon suyu ve şekerle demlenmesiyle pembe-yakut renk alan içecek hangisidir?', 'Reyhan şerbeti', ['Gelincik şerbeti', 'Kızılcık şerbeti', 'Nar çiçeği çayı'], 'Mor reyhan yapraklarındaki antosiyanin pigmentleri, ortama limon suyu gibi bir asit eklendiğinde morumsu koyu tondan parlak pembe-kırmızı renge dönüşür.'),
  ('Türk kahvesi yapımında en dengeli ısı iletimini sağladığı için ustalar tarafından yüzyıllardır tercih edilen geleneksel cezve malzemesi hangisidir?', 'İçi kalaylı kalın dövme bakır', ['İnce alüminyum levha', 'Sırsız gözenekli çömlek kil', 'Galvanizli teneke sac'], 'Kalın dövme bakır ısıyı tabandan yan duvarlara homojen biçimde yayar; kalay kaplama ise bakırın kahve asitleriyle tepkimeye girmesini önler.'),
  ('Anadolu\'da kız isteme merasimlerinde damat adayına tuzlu ya da biberli Türk kahvesi ikram edilmesi geleneği hangi sosyal davranışı ölçmeye yönelik sembolik bir sınamadır?', 'Damat adayının sabrını, olgunluğunu ve nezaketini sınamak', ['Damadın ailesinin maddi varlığını ve çeyiz gücünü öğrenmek', 'Misafirlerin kahve tadımındaki uzmanlık derecesini belirlemek', 'Nişan töreninin hangi mevsimde yapılacağına karar vermek'], 'Geleneksel kız isteme adetlerinde damadın tuzlu kahveyi yüzünü ekşitmeden içmesi sabırlı, hoşgörülü ve evliliğe istekli olduğunun göstergesi sayılır.'),
  ('Osmanlı kahvehanelerinde yüksekçe bir sedirde oturarak halka Köroğlu, Battal Gazi ve Hz. Ali cenkleri gibi hikâyeler anlatan geleneksel gösteri sanatçısına ne denirdi?', 'Meddah', ['Nakkaş', 'Hattat', 'Kâtip'], 'Kahvehaneler yalnızca içecek tüketilen yerler değil, meddahların baston ve mendil kullanarak tek kişilik hikâye canlandırmaları yaptığı sözlü kültür merkezleriydi.'),
  ('Anadolu\'da \'adaçayı\' ve \'dağ çayı\' (Sideritis türleri) hazırlanırken uçucu yağların kaybolmaması ve acılaşmaması için hangi yöntem uygulanmalıdır?', 'Kaynamış suyun ocaktan alındıktan sonra bitki üzerine dökülüp kapaklı kapta demlenmesi', ['Bitki dallarının soğuk suya konulup yirmi dakika harlı ateşte kaynatılması', 'Yaprakların önce tereyağında kavrulup ardından sütle pişirilmesi', 'Kurutulmuş çiçeklerin taş havanda tuzla dövülüp soğuk suyla çalkalanması'], 'Yaprak ve çiçek dokulu aromatik bitki çayları kaynatıldığında uçucu yağları buharlaşır ve acı bileşenler suya geçer; bu yüzden infüzyon (demleme) yöntemi kullanılır.'),
  ('Halk arasında \'yorgunluk kahvesi\'nden farklı olarak, bir kimseyle kurulan küçük bir dostluğun bile nesiller boyu unutulmayacağını vurgulayan ünlü atasözünde kahvenin ne kadar hatırı olduğu söylenir?', 'Kırk yıl', ['Yedi mevsim', 'Bin gece', 'Yüz asır'], '\'Bir fincan kahvenin kırk yıl hatırı vardır\' atasözü, Türk kültüründe kahve ikramının vefa ve kalıcı dostluk bağı kurmadaki simgesel gücünü anlatır.'),
  ('Kuzey Anadolu ve özellikle Kastamonu-Sinop çevresinde yabani kızılcık meyvesinin şekerle kaynatılıp kavanozlarda saklanan yoğun özünden yaz-kış suyla açılarak hazırlanan içecek hangisidir?', 'Kızılcık ekşisi şerbeti', ['Keçiboynuzu pekmezi', 'Andız özü', 'Sübye şurubu'], 'Kastamonu ve Batı Karadeniz\'de \'ekşi\' adı verilen konsantre kızılcık marmeladı/özü, suyla inceltilerek yemeklerin yanında mayhoş kızılcık şerbeti olarak tüketilir.'),
  ('Mardin ve Diyarbakır yöresinde kavrulmuş kahve çekirdeklerine öğütme aşamasında eklenerek Doğu Akdeniz ve Güneydoğu kahvelerine ferah, egzotik bir koku veren baharat tohumu hangisidir?', 'Kakule', ['Çemen otu', 'Kimyon', 'Sumak'], 'Zencefilgiller familyasından kakule (hel) kapsüllerinin içindeki siyah aromatik tohumlar, Mardin ve Hatay\'da Türk kahvesiyle birlikte çekilerek hoş koku verir.'),
  ('Geleneksel Türk kahvesi sipariş edilirken şeker oranını belirtmek için kullanılan terimler az şekerliden çok şekerliye doğru hangi sırayla dizilir?', 'Sade - Az şekerli - Orta - Şekerli', ['Kıtlama - Demli - Açık - Paşa', 'Telve - Köpüklü - Süvari - Mırra', 'Yumuşak - Kavruk - Çifte - Acı'], 'Türk kahvesinde şeker sonradan eklenmez; pişirme öncesinde cezveye konulan şeker miktarına göre sade, az, orta veya şekerli olarak hazırlanır.'),
  ('Anadolu\'nun pek çok yöresinde üzüm, dut, erik veya kayısı kurularının dilimlenip şekerli suda haşlanmasıyla yapılan ve yemeklerin yanında kâseyle kaşıklanarak içilen soğuk içecekli tatlı türü hangisidir?', 'Hoşaf', ['Komposto', 'Pelte', 'Zerde'], 'Farsça \'hoş-âb\' (güzel su) tamlamasından gelen hoşaf kuru meyvelerle hazırlanırken, taze meyvelerin şekerli suda kaynatılmasıyla yapılana komposto denir.'),
  ('Hoşaf ile komposto arasındaki farkı mutfak tekniği bakımından doğru açıklayan ifade aşağıdakilerden hangisidir?', 'Hoşafın kurutulmuş meyvelerden, kompostonun ise taze mevsim meyvelerinden hazırlanması', ['Hoşafın sütle pişirilmesi, kompostonun ise yalnızca pekmezle tatlandırılması', 'Hoşafın sıcak içilmesi, kompostonun ise dondurularak kalıp halinde kesilmesi', 'Hoşafın nişastayla koyulaştırılması, kompostonun ise kavrulmuş unla bağlanması'], 'Türk mutfak terminolojisinde kuru üzüm, kuru kayısı veya kuru erikten yapılan sulu meyve yiyeceğine hoşaf; taze şeftali, vişne veya elmadan yapılana komposto adı verilir.'),
  ('Kافkasya kökenli olup Anadolu\'da da yaygınlaşan, karnabahar görünümündeki simbiyotik maya ve bakteri taneciklerinin sütü fermente etmesiyle elde edilen probiyotik içecek hangisidir?', 'Kefir', ['Sübye', 'Şıra', 'Aşlama'], 'Kefir taneleri içerisindeki laktik asit bakterileri ve mayalar sütü fermente ederek hafif ekşimsi, köpüklü ve sindirimi destekleyen kefiri oluşturur.'),
  ('Karadeniz\'de çay toplama işinde uzun boylu bitki sıralarının üzerinden yaprakları kesip bez torbasına biriktiren geleneksel el aletine ne ad verilir?', 'Çay makası', ['Orak', 'Tırpan', 'Tahra'], 'Bir tarafına bez hazne takılan özel çay toplama makası, engebeli Rize ve Artvin yamaçlarında yaş çay yaprağı hasadında yaygın biçimde kullanılır.'),
  ('Güneydoğu Anadolu\'da sıcak yaz günlerinde buz kalıplarıyla soğutulan, dut veya vişne şurubunun rendelenmiş buz üzerine dökülmesiyle kâsede sunulan serinletici lezzet Adana\'da hangi adla bilinir?', 'Bici bici', ['Karsambaç', 'Haytalı', 'Zerde'], 'Adana\'nın tescilli sokak lezzeti bici bici; nişasta muhallebisi, rendelenmiş buz, gül suyu ve kırmızı şerbetle hazırlanıp serinletici şerbetli tatlı-içecek gibi tüketilir.'),
  ('Toros Dağları\'nın yüksek kesimlerindeki kuyularda saklanan temiz doğal karın pekmez veya bal şerbetiyle karıştırılmasıyla yapılan geleneksel serinletici hangisidir?', 'Karsambaç', ['Sübye', 'Boza', 'Hardaliye'], 'Yörük kültüründen günümüze ulaşan karsambaç, Toroslar ve Kahramanmaraş-Adana yaylalarında temiz kar üzerine üzüm/keçiboynuzu pekmezi veya şerbet dökülerek hazırlanır.'),
  ('Geleneksel Türk çayında bardağın dibinde hiç su payı kalmayacak biçimde koyu dem doldurulmasına kıraathane dilinde ne ad verilir?', 'Tavşan kanı veya demli', ['Paşa çayı', 'Kıtlama su', 'Süvari köpük'], 'İyi demlenmiş parlak yakut kırmızısı çaya \'tavşan kanı\' denir; açık ve çok sıcak su ağırlıklı (çoğunlukla çocuklara ılık verilen) çaya ise \'paşa çayı\' adı verilir.'),
  ('Çocuklara veya çok sıcak çay içemeyenlere ikram edilirken yarısına kadar demli çay koyup üzerini soğuk/ılık suyla tamamlayarak hazırlanan açık çaya halk arasında ne denir?', 'Paşa çayı', ['Kaçak çay', 'Yörük çayı', 'Mırra çayı'], 'İçimi kolaylaştırmak amacıyla sıcaklığı düşürülmüş ve rengi açılmış çaya günlük dilde \'paşa çayı\' denilmesi yaygın bir gelenektir.'),
  ('Mersin ve Silifke yöresinde yoğurdun yayıkta dövülmesi ya da tülbentte süzülüp nane ve soğuk kaynak suyuyla açılmasıyla elde edilen, Yörük çadırlarının temel içeceği hangisidir?', 'Silifke yayık ayranı', ['Tarsus kaynar şerbeti', 'Anamur muz nektarı', 'Mut erik kompostosu'], 'Silifke yoğurdundan hazırlanan yayık ayranı, koyun ve keçi sütü aromasıyla Toros Yörük kültürünün en tanınmış geleneksel içeceklerindendir.'),
  ('Gaziantep mutfağında kahvaltıdan sonra veya misafir ağırlamada sunulan \'zahter çayı\', hangi bitki grubunun kurutulmuş yaprak ve çiçeklerinden demlenir?', 'Yabani kekik (kara kekik) türü', ['Kurutulmuş dut yaprağı', 'Kavrulmuş arpa kavurgası', 'Yabani kuşburnu çekirdeği'], 'Güneydoğu ve Hatay\'da yaygın olan zahter (Thymbra spicata), keskin kekik aromasına sahip olup hem kahvaltılık toz karışım hem de sıcak bitki çayı olarak tüketilir.'),
  ('Sivas, Tokat ve Gümüşhane gibi karasal iklime sahip illerde sonbahar kırağısından sonra toplanan yabani gül meyvelerinin ezilip kaynatılmasıyla yapılan C vitamini deposu geleneksel içecek hangisidir?', 'Kuşburnu çayı ve nektarı', ['Demirhindi şerbeti', 'Sübye içeceği', 'Menengiç kahvesi'], 'Yabani gül (Rosa canina) meyvesi olan kuşburnu, Orta ve Kuzeydoğu Anadolu\'da hem marmelat hem de sıcak çay ve soğuk nektar olarak kış boyu tüketilir.'),
  ('İstanbul\'da tarihi yarımadada Mısır Çarşısı\'nın hemen yanı başında 1871\'den beri taze çekilmiş Türk kahvesi kokusuyla tanınan ünlü tahmis geleneği temsilcisi kimdir?', 'Kurukahveci Mehmet Efendi', ['Ali Muhiddin Hacı Bekir', 'Cemilzade Udi Cemil', 'Şekerci Cafer Erol'], '1871 yılında Tahmis Sokağı\'nda Mehmet Efendi tarafından çiğ kahvenin kavrulup dibekte dövülerek paketlenmiş halde satılması, Türk kahveciliğinde yeni bir dönem başlatmıştır.'),
  ('Anadolu\'da sonbahar başında buğdayın büyük bakır kazanlarda kaynatılıp kurutulması ve kabuğunun soyulup kırılmasıyla kışlık bulgur hazırlanırken komşulara dağıtılan haşlanmış buğdaya ne denir?', 'Hedik', ['Kavurga tanesi', 'Sütlü firik', 'Kurut ezmesi'], 'Bulgur kaynatma şenliklerinde kazandan ilk alınan haşlanmış tam buğday (hedik), ceviz veya şekerle çocuklara ve komşulara ikram edilir; diş buğdayı törenlerinde de yapılır.'),
  ('Güneydoğu Anadolu\'da başakları henüz tam kurumadan süt olum döneminin sonunda toplanıp saplarıyla birlikte ateşte tütsülenerek elde edilen isli yeşil buğday ürünü hangisidir?', 'Firik', ['Göce', 'Siyez', 'Düğü'], 'Yeşil buğday başaklarının alevde ütülüp ovuşturulmasıyla üretilen firik, isli aroması ve yüksek lif yapısıyla Gaziantep ve Hatay pilavlarının temel kışlık malzemesidir.'),
  ('Kayseri pastırmasının dış yüzeyine sıvanan \'çemen\' tabakasının etin bozulmadan uzun süre saklanmasındaki birincil işlevi nedir?', 'Hava ve mikroorganizma temasını kesip etin aşırı kuruyarak çatlamasını önlemek', ['Etin içindeki proteinleri birkaç saatte kaynatılmış gibi pişirmek', 'Pastırmanın ağırlığını su çekerek üç katına çıkarmak', 'Sığır etindeki tüm yağı dışarıya sızdırıp yok etmek'], 'Çemen otu (buy) tohumu unu, sarımsak ve kırmızı biberden oluşan çemen macunu; antimikrobiyal kalkan oluşturur, sinek/böcek temasını önler ve etin nem dengesini korur.'),
  ('Sonbahar sonlarında ekim sonu ile kasım ortası arasında yaşanan gündüzleri güneşli ve ılık, geceleri serin ve durgun hava koşullarının \'pastırma yazı\' diye adlandırılmasının nedeni nedir?', 'Tuzlanıp preslenen pastırmalık etlerin açık havada ideal hızda kurumasına en elverişli dönem olması', ['Çemen otunun yılda yalnızca kasım ayının ikinci haftasında çiçek açıp hasat edilmesi', 'Büyükbaş hayvanların yalnızca bu haftalarda yayladan şehre indirilmesine izin verilmesi', 'Kışlık odun fırınlarının bu sıcak günlerde yakılmasının yasaklanmış olması'], 'Gündüz ılık esinti ve gece serinliği, etin dışının birden kabuk bağlamadan içten dışa dengeli biçimde kurumasını ve olgunlaşmasını sağladığı için bu döneme pastırma yazı denmiştir.'),
  ('Ankara\'nın Çubuk ilçesiyle özdeşleşen coğrafi işaretli turşularda kavanoz dibine birkaç adet kuru nohut atılmasının hazırlık sürecine katkısı nedir?', 'Fermantasyonu başlatacak doğal karbonhidrat ve mikroflora desteğini hızlandırmak', ['Sarımsakların kavanoz içinde yeşermesini kesin olarak engellemek', 'Turşu suyunun rengini koyu yakut kırmızısına boyamak', 'Salatalıkların içindeki çekirdekleri eritip boşaltmak'], 'Kuru nohut, ortama laktik asit fermantasyonunu erken uyaran doğal bakteri ve nişasta desteği sağlayarak turşunun güvenle ekşimesine yardımcı olur.'),
  ('Gümüşhane\'de \'köme\', Elazığ\'da \'orcik\' ve Anadolu genelinde \'cevizli sucuk\' adıyla bilinen kışlık enerji besini hazırlanırken ipe dizilen ceviz içleri hangi karışıma batırılır?', 'Üzüm veya dut şırasının un ya da nişastayla pişirilmesiyle elde edilen pelteye', ['Kavrulmuş susam ezmesi ile süzme çam balının kaynatılmamış karışımına', 'Keçi sütü, salep ve şekerle dondurulan yoğun muhallebiye', 'Kuru incir püresi ile zeytinyağının fırınlanmış hamuruna'], 'İpe dizilmiş cevizler, üzüm ya da dut şırasının un/nişasta ve bazen sütle kaynatılmasıyla yapılan koyu kıvamlı \'herle\' kazana birkaç kez batırılıp asılarak kurutulur.'),
  ('Meyve şırasının nişasta veya unla pişirilip temiz bezler üzerine incecik yayılarak güneşte kurutulmasıyla elde edilen katlanabilir yaprak biçimindeki kışlık tatlı besin hangisidir?', 'Pestil', ['Cezerye', 'Zerde', 'Pişmaniye'], 'Gümüşhane, Bitlis, Malatya ve Gaziantep\'te (bastık adıyla) yaygın üretilen pestil; dut, üzüm, kayısı veya erik özünün ince tabaka halinde kurutulmasıyla saklanır.'),
  ('Geleneksel kışlık ev eriştesi kesildikten sonra bez örtüler üzerinde kurutulurken nem oranının yeterince düşürülmemesi saklama sırasında hangi soruna yol açar?', 'Bez torbalarda küflenme ve hamurumsu ekşi koku oluşması', ['Eriştelerin kendi kendine karamelize olup şekerlenmesi', 'Haşlama suyuna atıldığında hiç şişmeden taş gibi sert kalması', 'Yumurtanın hamur içinden sızarak tuzu kristalleştirmesi'], 'Un, yumurta, süt ve tuzla yoğrulan eriştenin kış boyu küflenmeden dayanması için gölgede veya hafif fırınlanarak kırılgan kuruluğa ulaştırılması şarttır.'),
  ('Hatay ve Gaziantep mutfaklarında kışlık \'güneş salçası\' (tepsi salçası) hazırlanırken ezilmiş domates veya kapya biber püresinin geniş tepsilerde güneşte bekletilmesi hangi koruma ilkesine dayanır?', 'Buharlaşmayla su oranının düşürülmesi ve kaya tuzu ilavesiyle mikrobiyal üremenin durdurulması', ['Domates asidinin güneş altında tamamen bazik kirece dönüşmesi', 'Tepsideki metal iyonlarının püre içindeki tüm şekeri alkole çevirmesi', 'Havadaki polenlerin salça yüzeyinde sert bir mum tabakası örmesi'], 'Güneşte koyulaştırılan salçada serbest su aktivitesi düşer; eklenen kaya tuzu ve yüzeyine gezdirilen zeytinyağı küflenmeyi önleyerek yoğun aromayı korur.'),
  ('Tokat\'ın Erbaa ilçesiyle özdeşleşen coğrafi işaretli salamura bağ yaprağını sarmalık olarak üstün kılan fiziksel yaprak özellikleri nelerdir?', 'İnce dokulu, tüysüz, damarsız ve derin olmayan dilimli yapıda olması', ['Kalın derimsi kabuklu, yoğun tüylü ve koyu mor damarlı olması', 'Avuçtan küçük tek parçalı ve sert tırtıklı kenarlara sahip olması', 'Tuzlu suda haşlandığında kolayca dağılan süngerimsi kalınlıkta olması'], 'Narince üzüm çeşidinden toplanan Tokat Erbaa bağ yaprağı; ince, tüysüz, ince damarlı ve sarımsı yeşil rengiyle sarma mutfağının en makbul salamuralık yaprağıdır.'),
  ('Orta Anadolu\'da uzun kış gecelerinde çerez olarak tüketilmek üzere buğday tanelerinin kavurma sacında çıtırdayana dek susuz kavrulması ve içine kenevir tohumu (çedene) veya ceviz katılmasıyla yapılan yiyecek hangisidir?', 'Kavurga', ['Hedik', 'Keşkek', 'Tutmaç'], 'Kuru buğdayın bazen mısır, nohut veya çedene ile birlikte sac üzerinde kavrulmasıyla hazırlanan kavurga, Anadolu\'nun en eski kışlık kuru atıştırmalıklarındandır.'),
  ('Malatya kayısısının hiçbir kimyasal işleme uğratılmadan doğrudan güneş altında doğal haliyle kurutulması sonucu koyu kahverengi renk alan çeşidine ne ad verilir?', 'Gün kurusu', ['Şekerpare islimi', 'Çağla salamurası', 'Zerdali pestili'], 'Kükürtlenmeden doğrudan güneşte kuruyan kayısı, doğal enzimatik esmerleşmeyle koyu kehribar-kahve rengini alır ve \'gün kurusu\' adıyla yoğun aromasıyla tüketilir.'),
  ('Ege Bölgesi\'nde sonbaharda hasat edilen yeşil zeytinlerin acılığını veren \'oleuropein\' maddesini uzaklaştırıp tatlandırmak için evlerde uygulanan en yaygın iki geleneksel hazırlık yöntemi hangisidir?', 'Taşla kırma veya bıçakla çizip belirli aralıklarla suyunu değiştirme', ['Zeytinleri süt içinde kaynatıp unla kaplayarak fırınlama', 'Meyveleri sirke ve şeker şurubunda dondurucuda bekletme', 'Çekirdeklerini çıkarıp üzüm pekmeziyle güneşte kavurma'], 'Yeşil zeytin kırılarak ya da çizilerek suya yatırılır; acı glikozit olan oleuropein suya geçtikçe tatlı su değiştirilir ve ardından kaya tuzu-limon tuzu salamurasına alınır.'),
  ('Karadeniz kıyı şeridinde bol avlandığı kış aylarında temizlenip kafası koparılan hamsilerin fıçılara veya tenekelere kalın tuz tabakalarıyla istiflenerek saklanan geleneksel ürününe ne denir?', 'Tuzlama (Salamura) hamsi', ['Çiroz uskumru', 'Lakerda torik', 'Pastırma sazan'], 'Doğu Karadeniz\'de hamsi avının yoğun olduğu dönemde balıklar iri tuz ve defne yaprağıyla küp veya tenekelere basılarak yaz ve tarla mevsimi için \'hamsi tuzlaması\' yapılır.'),
  ('Gaziantep ve Kilis\'te kışlık yemeklere ekşilik vermek amacıyla henüz kızarmamış veya yeni alaca düşmüş tane sumakların ya da narların işlenmesiyle elde edilen koyu kıvamlı soslardan \'nar ekşisi\' yapılırken nar suyuna ne eklenir?', 'Şeker veya glukoz katılmadan yalnızca kendi öz suyu bakır kazanda koyulaşana dek kaynatılır', ['Kıvam alması için bol miktarda mısır nişastası ve üzüm sirkesi katılır', 'Renginin kararması için keçiboynuzu unu ve kavrulmuş arpa eklenir', 'Acılığını kesmek amacıyla pekmez toprağı ve yumurta akı çırpılır'], 'Gerçek geleneksel nar ekşisi (%100 nar ekşisi), ekşi veya mayhoş narların suyunun hiçbir şeker, tuz veya katkı eklenmeden ağır ateşte uçurulup yoğunlaştırılmasıyla elde edilir.'),
  ('Karadeniz mutfağında lahana, taze fasulye, sakarca veya taflan (karayemiş) gibi gıdaların kışa saklanmak üzere bol kaya tuzuyla küplere basılıp gerektiğinde tuzu suda alınarak soğanla kavrulmasına ne ad verilir?', 'Turşu kavurması', ['Ekşili tirit', 'Zeytinyağlı pilaki', 'Sütlü borani'], 'Doğu Karadeniz\'de fasulye veya taflan tuzlaması/turşusu yalnızca soğuk yenmez; fazla tuzu suda süzüldükten sonra mısır yağı veya tereyağında bol soğanla kavrularak sıcak yemek yapılır.'),
  ('Kayseri, Yozgat ve Sivas köylerinde sonbaharda kışlık yufka ekmekleri imece usulüyle sac üzerinde yüzlerce adet pişirildikten sonra nasıl muhafaza edilir ve tüketim öncesi nasıl yumuşatılır?', 'Kuru ve serin yerde üst üste istiflenip yeneceği zaman üzerine su serpilerek bez altında nemlendirilir', ['Tuzlu ayran fıçılarına batırılıp dondurularak yeneceği gün yağda kızartılır', 'Zeytinyağı küplerinde saklanıp servis öncesi şekerli şerbette kaynatılır', 'Toprak altına samanla gömülüp çıkarıldığında doğrudan kuru olarak ufalanır'], 'İnce açılıp sacda kurutulan kışlık \'işkefe / kuru yufka\' ekmeği aylarca küflenmez; sofraya gelmeden yarım saat önce su serpilip (\'sulama\') sofra bezine sarıldığında taze ekmek gibi yumuşar.'),
  ('Kışlık erzak hazırlıklarında \'imece\' geleneğinin Anadolu köy ve mahalle yaşamında üstlendiği toplumsal ve ekonomik işlev aşağıdakilerden hangisidir?', 'Yoğun iş gücü gerektiren erişte, tarhana, salça ve yufka işlerini komşuluk dayanışmasıyla kısa sürede tamamlamak', ['Üretilen tüm kışlık yiyecekleri tek bir tüccara vergi karşılığında devretmek', 'Köydeki ailelerin birbirinden habersiz gizli tarifler geliştirmesini zorunlu kılmak', 'Tarımsal üretimi durdurup yalnızca hazır paketli şehir gıdaları satın almak'], 'İmece, tek bir hanenin günlerce uğraşacağı kışlık yufka açma, bulgur kaynatma, erişte kesme ve bağ bozumu işlerinin sırayla el birliğiyle şenlik havasında bitirilmesidir.'),
  ('Afyonkarahisar ve Konya çevresinde haşhaş kapsüllerinden elde edilen sarı veya mavi tohumların taş değirmenlerde kavrulup ezilmesiyle üretilen, kışlık hamur işlerinde (bükme, çörek, katmer) yağ yerine kullanılan yoğun ezme hangisidir?', 'Sürtme haşhaş ezmesi', ['Susam tahini', 'Menengiç macunu', 'Çemen lapası'], 'Haşhaş tohumları kavrulup geleneksel taşlarda yağını salana dek ezilerek \'haşhaş ezmesi\' elde edilir; Afyon, Uşak ve Eskişehir kışlık hamur işlerinin vazgeçilmez iç harcıdır.'),
  ('Doğu Anadolu\'da (Erzurum, Kars, Van, Ağrı) kışlık erzakların muhafazası için evin kuzey cephesinde, penceresiz veya küçük mazgallı, taş duvarlı ve toprak damlı serin bölmeye geleneksel konut mimarisinde ne ad verilir?', 'Kiler (Mereğe bitişik erzak odası / Hazine)', ['Başoda (Selamlık divanı)', 'Hayat (Güneşli avlu)', 'Cumba (Sokağa taşan çıkma)'], 'Geleneksel Anadolu evlerinde kuzeye bakan kalın taş veya kerpiç duvarlı, güneş almayan \'kiler / hazine odası\', küp peynirlerin, kavurma, un, bulgur ve turşuların doğal soğuk deposudur.'),
  ('Antalya, Mersin ve Muğla kıyılarında baharda bollaşan turunç meyvelerinin etli iç kısmı ekşi sos yapılırken, kalın turuncu dış kabukları kışlık sofralar için nasıl değerlendirilir?', 'Acılığı birkaç su haşlanıp tatlandırılarak rulo halinde ipe dizilip turunç kabuğu reçeli yapılır', ['Tuzlu balık fıçılarına sarımsak yerine ezilerek lakerda mayası yapılır', 'Kurutulup öğütülerek ekmeklik buğday ununun yerine kullanılır', 'Zeytin kırma taşlarının altında ezilerek acı yemeklik yağ çıkarılır'], 'Akdeniz mutfağında atıksız mutfak anlayışıyla turunç kabukları incecik rendelenir, rulo sarılıp ipe dizilir, acısı suda alındıktan sonra parlak turunç reçeline dönüştürülür.'),
  ('Elazığ ve Malatya\'da dut, kayısı veya üzüm pestillerinin arasına dövülmüş ceviz ya da badem içi konulup muska ya da rulo biçiminde katlanarak kış boyu ikram edilen enerji atıştırmalığına ne denir?', 'Cevizli pestil sarması', ['Kaymaklı ekmek kadayıfı', 'Fıstıklı tel kadayıf', 'Şerbetli revani dilimi'], 'Yumuşak pestil yapraklarının içine ceviz, fındık veya bal-kaymak karışımı sürülüp üçgen muska veya rulo şeklinde sarılması Doğu Anadolu ve Gümüşhane\'nin en bilinen kışlık ikramıdır.'),
  ('Muğla, Denizli ve Aydın dağ köylerinde kışlık olarak bütün halde soyulup iplere asılarak ya da sergilere dizilerek dışı pudramsı doğal şeker bağlayana dek kurutulan buruk meyve hangisidir?', 'Trabzon hurması (Cennet elması) kurusu', ['Taze yenidünya', 'Sulu karpuz dilimi', 'Yabani böğürtlen tanesi'], 'Tazeyken sert çeşitleri buruk olan cennet hurması soyulup iplere asılarak rüzgârda kurutulduğunda burukluğunu yitirir, lokum kıvamına gelir ve dışında doğal glukoz kristalleri oluşur.'),
  ('Kışlık kuru fasulye, nohut ve mercimek kavanozlarına ya da bez torbalarına böceklenmeyi (baklagil tohum böceğini) önlemek amacıyla Anadolu\'da geleneksel olarak hangi doğal koruyucular konulur?', 'Kuru defne yaprağı, kaya tuzu parçası veya sarımsak dişi', ['Taze kesilmiş domates dilimi ve ıslak nane dalı', 'Yumuşak ekmek içi ve toz şeker kaşıklaması', 'Haşlanmış patates kabuğu ve tatlı badem içi'], 'Kuru defne yaprağının uçucu yağları (sineol) ve kaya tuzunun nem çekici etkisi, kuru baklagil kavanozlarında bitlenme ve kelebeklenmeyi doğal yolla azaltır.'),
  ('Kışlık konserve (menemenlik domates sosu veya fasulye konservesi) hazırlanırken kavanozların kaynatılıp yeni kapakla sıkıca kapatılmasının ardından iç basıncın düşerek kapağın içe doğru çökmesi neyi kanıtlar?', 'Hava geçirmez vakum oluştuğunu ve dışarıdan mikroorganizma girişinin kesildiğini', ['Kavanoz içindeki domateslerin tamamen çürüyüp gaz ürettiğini', 'Tuz oranının aşırı yüksek olup camı eritmeye başladığını', 'Konservenin hemen açılıp çöpe atılması gerektiğini'], 'Sıcak dolum sonrası soğuyan kavanoz tepe boşluğundaki buhar yoğuşur ve kısmi vakum oluşur; kapağın ortasının içe çökük olması güvenli sızdırmazlığın göstergesidir; şişkin kapak ise bozulma (Clostridium botulinum riski) uyarısıdır.'),
  ('Gümüşhane ve Bayburt yöresinde kışlık kurutulmuş taze fasulye, erişte, yarma, mercimek ve kurut (keş) kullanılarak pişirilen besleyici kış çorbası geleneğinde bakliyatların bir gece önceden ıslatılmasının amacı nedir?', 'Kuru tanelerin su alarak yumuşamasını, pişme süresinin kısalmasını ve gaz yapıcı oligosakkaritlerin suya geçmesini sağlamak', ['Bakliyatların içindeki tüm bitkisel proteini yıkama suyuna akıtıp uzaklaştırmak', 'Tanelerin dış kabuğunu sertleştirerek tencerede hiç açılmamasını sağlamak', 'Mercimek ve nohudun nişastasını şekere çevirip çorbayı tatlandırmak'], 'Kuru baklagillerin ıslatılması ve ıslatma suyunun dökülmesi hem fitik asit ile rafinoz/stakiyoz gibi gaz yapıcı şekerleri azaltır hem de nişasta jelatinleşmesini hızlandırır.'),
  ('Bursa mutfağının simgesi olan ve döner yapraklarının pide, domates sosu, yoğurt ile kızgın tereyağı eşliğinde sunulduğu kebap, 19. yüzyılın ikinci yarısında hangi usta tarafından geliştirilmiştir?', 'Kayhan Çarşısı\'nda çalışan İskender Efendi', ['Kapalıçarşı\'da aşçılık yapan Hacı Sadık Usta ve oğulları', 'Uludağ eteklerinde konak işleten Mehmed Kâmil Efendi', 'Tahtakale hanlarında kebapçılık yapan Halepli Şems Usta'], 'Bursa Kayhan semtinde Mehmet oğlu İskender Efendi, yatay ateşte pişen kuzu çevirmeyi dikey ocağa uyarlayarak bugünkü döner ve İskender kebabı geleneğini başlatmıştır.'),
  ('Gaziantep\'te sabahın erken saatlerinde esnaf ve halk tarafından kahvaltıda tüketilen, haşlanmış kuzu gerdan eti, pirinç, sarımsak ve yoğun iç yağıyla harlı ateşte sahan içinde hazırlanan çorba-yemek hangisidir?', 'Beyran', ['Terbiyeli ve nohutlu bayram yuvalaması', 'Süzme yoğurtla bağlanan şiveydiz aşı', 'Sumak ekşisiyle pişirilen kuru patlıcan dolması'], 'Saatlerce kısık ateşte haşlanan kuzu etinin bakır sahanda pirinç, et suyu, pul biber ve sarımsakla harlı alev üzerinde özleştirilmesiyle yapılan beyran, Gaziantep\'in tescilli sabah yemeğidir.'),
  ('Közlenmiş patlıcanların ezilip sarımsaklı süzme yoğurtla karıştırıldığı yatağın üzerine tereyağında kavrulmuş kuşbaşı veya kıymalı kuzu eti konularak hazırlanan Gaziantep lezzeti hangisidir?', 'Alinazik kebabı', ['Beşamel soslu patlıcanla yapılan hünkârbeğendi', 'Fırında domatesle pişirilen saksı kebabı', 'Kuyruk yağıyla zırhta çekilen haşhaş kebabı'], 'Yavuz Sultan Selim\'in Antep ziyareti sırasında ikram edildiği rivayet olunan Alinazik kebabı, köz patlıcanlı sarımsaklı yoğurt ve sıcak kuzu etinin uyumuyla tanınır.'),
  ('Siirt ve Bitlis yörelerinde yaklaşık iki-üç metre derinliğindeki toprağa gömülü kuyuların kapağı çamurla sıvanarak kuzu veya oğlak etinin kendi buharıyla kemikten sıyrılacak kıvamda pişirildiği kebap hangisidir?', 'Büryan kebabı', ['Yatay şişe takılıp odun alevinde kesilen cağ kebabı', 'Bakır tepside domates ve biberle fırınlanan tepsi kebabı', 'Toprak çömlek içinde ağzı hamurla kapatılan testi kebabı'], 'Kuyu tabanındaki kor ateşin üzerine su dolu bakır kazan konulup etlerin çengellerle sarkıtılması ve kuyu ağzının çamurla kapatılmasıyla yapılan büryan, Siirt ve Bitlis adına tescillidir.'),
  ('Siirt mutfağında keklik veya tavuk eti, badem, çam fıstığı, kuş üzümü ve baharatlı iç pilavın kek kalıbı biçimindeki bakır tencereye sıvanan ince hamur kılıfı içinde fırınlandığı simgesel düğün yemeği hangisidir?', 'Perde pilavı', ['Havuç rendesi ve kuzu etiyle demlenen Özbek pilavı', 'Safranlı su ve bademle renklendirilen saray pilavı', 'Yeşil mercimek ve kavrulmuş soğanla yapılan müceddere'], 'Fes benzeri ayaklı özel bakır tencerede tereyağlı badem dizilip yufka hamuruyla kaplanan Siirt perde pilavında her malzeme yeni kurulan yuvadaki bolluk ve mahremiyeti simgeler.'),
  ('Diyarbakır ve Mardin mutfaklarında kuzu sağ kaburgasının cep gibi açılıp bademli, yenibaharlı ve karabiberli iç pilavla doldurularak dikildikten sonra ağır ateşte buharda haşlanıp kızartılmasıyla hazırlanan ziyafet yemeği hangisidir?', 'Kaburga dolması', ['Temizlenmiş koyun bağırsağına pirinç doldurulan bumbar', 'İnce bulgur kabuğu içine kıymalı harç konulan içli köfte', 'Asma yaprağına koruk ekşili pirinç sarılan zeytinyağlı dolma'], 'Özellikle Diyarbakır ve Mardin konak sofralarında saatler süren özenli pişirme gerektiren kaburga dolması, baharatlı iç pilavın et dokusuyla bütünleştiği görkemli bir yemektir.'),
  ('Hatay\'da zırhla çekilmiş dana veya kuzu kıymasının maydanoz, sarımsak, biber ve baharatlarla yoğrulup yuvarlak bakır tepsiye ince bir tabaka halinde basılarak taş fırında pişirildiği coğrafi işaretli kebap hangisidir?', 'Antakya tepsi kebabı', ['Şişe dizilmiş patlıcan dilimleriyle közlenen kazan kebabı', 'Küp doğranmış ciğerin kuyruk yağıyla kavrulduğu kartalak', 'Yufka arasına sarılıp üzerine yoğurt gezdirilen beyti sarma'], 'Yörede Arapça kökenli \'lahm-ı sini\' adıyla da bilinen Antakya tepsi kebabı, üzerine biber salçalı su gezdirilip domates ve yeşil biber dilimleriyle taş fırında pişirilir.'),
  ('Çukurova (Adana ve Mersin) mutfağında minik kulak mantılarının ve haşlanmış nohudun naneli, limonlu ve salçalı et suyunda pişirilmesiyle hazırlanan ünlü yöresel çorba-yemek hangisidir?', 'Yüksük çorbası', ['Kızarmış hamur lokmalarıyla sunulan tatar böreği', 'Süzme yoğurt ve dövmeyle soğuk içilen ayran aşı', 'Kavrulmuş un ve tavuk suyuyla yapılan arabaşı çorbası'], 'Hamur karelerinin dikiş yüksüğü kadar küçük kapatılmasından adını alan yüksük çorbası, Adana ve Mersin sofralarında ana yemek gücünde sunulan ekşili-naneli bir çorbadır.'),
  ('Adana, Kahramanmaraş ve Malatya mutfaklarında kıymalı büyük içli köfteler (\'ana\') ile bulgurdan yuvarlanan nohut büyüklüğündeki sade minik köftelerin (\'kız\') nohutlu ekşili suda birlikte pişirildiği yemek hangisidir?', 'Analı kızlı', ['Kuru erik ve kuzu etiyle pişirilen tatlı-ekşi mutancana', 'Haşlanmış işkembe ve nohutla hazırlanan tuzlama aşı', 'Yarma buğday ve kaz etiyle fırınlanan düğün keşkeği'], 'Yapımı büyük el emeği isteyen analı kızlı yemeğinde kıymalı harç taşıyan iri köfteler anayı, yanında pişen yüzlerce minik bulgur yuvarlağı ise kızları temsil eder.'),
  ('Yozgat, Konya, Karaman ve Kırşehir yörelerinde kış gecelerinin simgesi olan \'arabaşı\' geleneğinde acılı tavuk, kaz veya hindi çorbasının yanında sunulan ve çiğnenmeden çorbayla birlikte yutulan soğuk muhallebimsi hamura ne denir?', 'Arabaşı hamuru', ['Suda haşlanmış kulak mantısı taneleri', 'Sac üzerinde kurutulmuş gevrek şebit yufkası', 'Tereyağında kızartılmış bayat somun kıtırları'], 'Un, su ve tuzun pişirilip tepsiye dökülerek soğutulmasıyla jöle kıvamı alan baklava dilimli soğuk hamur, kaşığın ucuna alınıp kaynar acılı çorbaya daldırılarak çiğnenmeden yutulur.'),
  ('Yozgat, Nevşehir ve Kayseri yörelerinde arpacık soğan, nohut, sarımsak ve kuşbaşı etin sırlı veya sırsız toprak kap içine konulup ağzı hamurla sıvanarak kor ateşte pişirildiği ve servis sırasında kabın kırıldığı yemek hangisidir?', 'Testi kebabı', ['Bakır sahan içinde kuzu beyniyle pişirilen beykoz kebabı', 'Yağlı kâğıda sarılıp fırınlanan sebzeli kağıt kebabı', 'Közlenmiş patlıcan püresi üzerinde sunulan tas kebabı'], 'Orta Anadolu çömlekçilik geleneğiyle bütünleşen testi (desti) kebabında buhar dışarı kaçmadığı için et kendi sebze suyunda lokumlaşır; sofrada testinin boynu kırılarak servis edilir.'),
  ('Samsun, Sinop, Kastamonu ve Konya başta olmak üzere Anadolu\'nun pek çok yöresinde kaz, ördek, hindi veya kemikli kuzu etinin yağlı suyuna kuru yufka, pide ya da bayat ekmeklerin doğranıp ıslatılmasıyla yapılan köklü yemeğe ne ad verilir?', 'Tirit', ['Haşlanmış buğday ve nohutla dövülen keşkek', 'Yoğurtlu sarımsaklı sosla sunulan siron', 'İnce bulgur ve salçayla yoğrulan batırık'], 'Bayat ekmek ve kuru yufkayı değerlendirme bilgeliğine dayanan tirit; Samsun-Kavak\'ta kaz eti ve bulgur pilavıyla, Konya\'da ise şiş köfte, sumaklı soğan ve süzme yoğurtla tescilli bir ziyafet yemeğine dönüşmüştür.'),
  ('Eskişehir mutfağıyla özdeşleşen ve 19. yüzyılda Kırım Tatar göçmenlerinin Anadolu\'ya taşıdığı, yarım ay biçimindeki ince hamurun içine çiğ soğanlı sulu kıyma harcı konulup kızgın yağda saniyeler içinde pişirilen börek hangisidir?', 'Çibörek', ['Haşlanmış hamur katlarıyla fırınlanan su böreği', 'Peynirli ve maydanozlu rulo sarılan sigara böreği', 'Haşhaş ezmesi ve cevizle bükülen Afyon ağzıaçığı'], 'Kıpçak-Tatar Türkçesinde \'nefis, lezzetli börek\' anlamına gelen \'şırbörek / çibörek\', kıyma harcına su katılması sayesinde pişerken içten buharla sulu kalır ve yağ çekmeden kabarır.'),
  ('Anadolu düğün, bayram ve hayır pilavlarının en köklü törensel yemeği olup buğday (yarma/dövme) ile etin dev kazanlarda tahta tokmaklarla saatlerce dövülerek sakızımsı bir kıvama getirildiği UNESCO tescilli miras hangisidir?', 'Keşkek', ['Kuru fasulye ve mısırla kaynatılan aşure', 'Nohut ve işkembeyle hazırlanan düğün çorbası', 'Pirinç unu ve tavuk göğsüyle dövülen herise tatlısı'], '2011 yılında Türkiye adına UNESCO Somut Olmayan Kültürel Miras Listesi\'ne kaydedilen geleneksel keşkek töreni, imece ruhuyla buğday ve etin homojen lifli bir doku alana dek dövülmesine dayanır.'),
  ('Sakarya ve Adapazarı mutfağının simgesi olan \'ıslama köfte\' sunulurken dilimlenmiş bayat köy ekmekleri hangi karışıma batırılıp ızgarada kızartılarak köftenin altına dizilir?', 'Kemik suyu, kırmızı toz biber ve sıvı yağdan oluşan sıcak sosa', ['Sarımsaklı süzme yoğurt ile taze sıkılmış limon suyunun karışımına', 'Domates salçası, üzüm sirkesi ve nar ekşisiyle kaynatılan terbiyeye', 'Süt, çırpılmış yumurta ve rendelenmiş kaşar peynirli bulamaca'], 'Balkan göçmenlerinin bayat ekmeği değerlendirme alışkanlığından doğan Adapazarı ıslama köftesinde, kara fırın ekmeği dilimleri kırmızı biberli kemik suyuna batırılıp kömür ızgarasında gevretilir.'),
  ('Trabzon\'un Akçaabat ilçesiyle özdeşleşen coğrafi işaretli köftenin harcında kıyma, bayat ekmek ve tuzun yanı sıra baskın lezzeti veren zorunlu malzeme hangisidir?', 'İç yağı ve havanda dövülmüş taze sarımsak', ['İnce kıyılmış taze dereotu ve kavrulmuş çam fıstığı', 'Rendelenmiş kuru soğan, kimyon ve yenibahar', 'Haşlanmış pirinç kırığı ve kurutulmuş reyhan otu'], 'Akçaabat köftesinde soğan ve karışık baharatlar kullanılmaz; bölgede yetişen danaların etleri böbrek/iç yağı, bayat Trabzon ekmeği ve bol sarımsakla yoğrularak kömür ızgarasında pişirilir.'),
  ('Doğu Karadeniz (Trabzon ve Rize) yayla kahvaltılarının baş tacı olan \'kuymak / muhlama\' yapılırken bakır sahanda tereyağı ve mısır unu kavrulduktan sonra uzayan lifli dokuyu veren yöresel peynir hangisidir?', 'Trabzon kolot peyniri veya Rize telli (minci/çivil) peyniri', ['Koyun sütünden yapılan tam yağlı sert Ezine beyaz peyniri', 'Deri tulum içinde mağarada olgunlaştırılan Erzincan tulumu', 'Peynir altı suyunun kaynatılmasıyla elde edilen tuzsuz tatlı lor'], 'Fırınlanmış mısır unu yayla tereyağında kavrulup sıcak suyla açıldıktan sonra eklenen az tuzlu kolot veya telli peynir, ısıyla eriyip uzayarak kuymağın karakteristik kıvamını oluşturur.'),
  ('Karadeniz kıyı mutfağının en temel kış sebzesi olan karalahana (pancar), etli veya iç yağlı çorbası pişirilirken kıvam bağlamak ve besleyiciliği artırmak için geleneksel olarak hangi malzemelerle buluşturulur?', 'Barbunya fasulyesi, kırık mısır (yarma) ve mısır unu', ['Yeşil mercimek, ince köftelik bulgur ve haşhaş ezmesi', 'Kuru bakla, arpa şehriye ve süzme koyun yoğurdu', 'Nohut, kestane şekeri ve kavrulmuş susam tahini'], 'Doğu Karadeniz\'de \'lahana çorbası / pancar çorbası\' denilen günlük temel yemekte ince kıyılmış karalahana; mısır yarması, barbunya fasulyesi, iç yağı/acı biber ve bağlayıcı mısır unuyla kaynatılır.'),
  ('Rize ve Trabzon mutfağında baharatlı, kuş üzümlü ve çam fıstıklı iç pilavın fırın tepsisine veya tavaya kılçıkları ayıklanmış balıklarla dıştan sarılarak pişirildiği ünlü yöresel yemek hangisidir?', 'Hamsili pilav', ['Tuzlu palamut dilimleriyle soğuk kurulan balık pilakisi', 'Asma yaprağı içinde kömürde közlenen uskumru dolması', 'Safranlı sebze suyunda haşlanan kalkan balığı buğulaması'], 'Hamsili pilavda mısır ununa bulanmış kılçıksız hamsiler tavanın tabanını ve yan duvarlarını tamamen kaplar, ortasına karabiberli-yenibaharlı kuş üzümlü pilav konup üstü yine hamsiyle kapatılarak pişirilir.'),
  ('Muğla ve Bodrum mutfağıyla özdeşleşen \'çökertme kebabı\'nda jülyen doğranıp marine edilmiş dana bonfile dilimleri hangi çıtır altlık üzerinde sarımsaklı yoğurt ve domates sosuyla sunulur?', 'Kibrit çöpü inceliğinde doğranıp kızartılmış patates', ['Tereyağında kavrulmuş tel şehriyeli pirinç pilavı', 'Közlenmiş bostan patlıcanı ve kapya biber ezmesi', 'Et suyuyla ıslatılıp fırınlanmış tırnak pide küpleri'], 'Milas-Bodrum hattından tüm ülkeye yayılan çökertme kebabının imza dokusu, nişastası suda alındıktan sonra altın sarısı çıtırlıkta kızartılan kibrit patates yatağıdır.'),
  ('İzmir, Aydın ve Muğla kıyılarında yaz sabahları güneş doğmadan hemen önce açtığında koparılıp yırtılmadan pirinçli, dereotlu ve naneyle zeytinyağlı olarak doldurulan narin sebze çiçeği hangisidir?', 'Kabak çiçeği', ['Enginarın dikenli mor püskül yaprakları', 'Bamya bitkisinin olgunlaşmış tohum kapsülü', 'Ayçiçeği tablasının dış sarı taç yaprakları'], 'Öğle sıcağında kapanıp büzüştüğü için sabah çiğiyle toplanan sarı kabak çiçekleri, Ege ve Girit-Sefarad mutfağının en zarif zeytinyağlı dolma malzemesidir.'),
  ('İzmir\'in Urla ve Çeşme yarımadasıyla özdeşleşen coğrafi işaretli \'sakız enginarı\'ndan zeytinyağlı bütün enginar dolması yapılırken çanak yaprakların arasına hangi taze ot cömertçe yerleştirilir?', 'İnce kıyılmış taze dereotu ve taze soğan', ['Kurutulmuş dağ kekiği ve ezilmiş çemen yaprağı', 'Kavrulmuş ısırgan otu ve dövülmüş kişniş tohumu', 'Mor reyhan yaprakları ve haşlanmış evelik sapı'], 'Çanak enginarla birlikte körpe dış yapraklarıyla bütün pişirilen İzmir usulü enginar dolmasında pirinçli iç harcın ruhunu bol dereotu, taze soğan, karabiber ve sızma zeytinyağı oluşturur.'),
  ('İzmir sokak kültüründe 15. yüzyıldan itibaren Sefarad Yahudilerinin mutfak geleneğiyle şehre yerleşen ve un, su, tuz hamurunun sıvı yağ içinde dinlendirilip katlanarak yüksek ısılı fırında pişirildiği gevrek hamur işi hangisidir?', 'Boyoz', ['Pekmezli suya batırılıp susamlanan İzmir gevreği', 'Nohut mayalı özel ekmek arasına konulan kumru', 'Lavaş içinde soğuk kuzu kelle etinden yapılan söğüş'], 'İspanyolca \'bollos\' (küçük çörekler) sözcüğünden gelen İzmir boyozu, mayasız hamurun yağla el altında defalarca katlanıp açılmasıyla milföy benzeri pul pul katman kazanır ve fırınlanmış katı yumurtayla yenir.'),
  ('Antalya mutfağının coğrafi işaretli \'piyaz\'ını Türkiye\'nin diğer yörelerindeki kuru fasulye piyazlarından ayıran en özgün sos bileşimi nedir?', 'Sarımsak, limon suyu, üzüm sirkesi ve suyla inceltilmiş bol susam tahini', ['Közlenmiş kapya biber, nar ekşisi, ceviz içi ve acı isotla çırpılmış yoğun sos', 'Süzme koyun yoğurdu, kuru nane, eritilmiş tereyağı ve haşhaş ezmesi karışımı', 'Domates salçası, balık suyu, defne yaprağı ve karabiberle kaynatılmış sıcak sos'], 'Küçük taneli Çandır fasulyesiyle hazırlanan Antalya piyazı bir yan salata değil ana yemek niteliğindedir; üzerine tahin-sarımsak-sirke-limon taratoru dökülür ve katı yumurta, domates dilimleriyle tamamlanır.'),
  ('Doğu Anadolu ve Güneydoğu Anadolu\'da özellikle yaz sıcaklarında haşlanmış aşurelik buğday (dövme), nohut ve soğuk ayranın taze nane veya aşotu (kişniş) yapraklarıyla pişirilmeden ya da soğutularak sunulduğu çorba hangisidir?', 'Ayran aşı çorbası', ['Kemik suyunda sarımsak ve sirkeyle kaynatılan kelle paça', 'Kavrulmuş tarhana ve salçayla koyulaştırılan kış çorbası', 'Tavuk suyu ve tel şehriyeyle hazırlanan hasta çorbası'], 'Erzurum\'da \'aşotu\' (taze kişniş) ve küçük köftelerle ılık veya soğuk, Van ve Hakkâri\'de kabak ve yayla otlarıyla, Güneydoğu\'da ise buzlu naneli soğuk çorba (mehîr) olarak tüketilen ayran aşı köklü bir yayla mirasıdır.'),
  ('Sivas, Tokat ve Amasya kırsalında ilkbahar yağmurlarıyla tarlalarda kendiliğinden biten, ince kıyılıp bulgur, çemen/pastırma, sarımsak ve sütle veya yoğurtla pişirilen koyu yeşil yabani ot yemeği hangisidir?', 'Madımak yemeği', ['Zeytinyağı ve portakal suyuyla pişirilen kereviz yemeği', 'Pirinç ve kuru soğanla hazırlanan semizotu bastısı', 'Haşlanıp sarımsaklı limon sosuyla yenilen deniz börülcesi'], 'Türkülere de konu olan madımak (Polygonum cognatum), Sivas başta olmak üzere Orta Anadolu\'da bahar aylarında toplanıp tahta satırla incecik kıyılarak bulgur ve çemenli pastırmayla pişirilir.'),
  ('Kars, Ardahan ve Iğdır mutfaklarında kış ortasında misafir onuruna hazırlanan kaz eti yemeğinde, tuzlanıp ayazda kurutulmuş kazın fırınlanırken altına yayılan bulgur pilavı lezzetini nereden alır?', 'Askıda veya ızgarada pişen kazdan tepsiye damlayan saf kaz yağından', ['Pilav suyuna sonradan katılan kavrulmuş fındık yağı ve sütten', 'Tepsi tabanına döşenen domates salçası, krema ve kaşar peynirinden', 'Bulgurun haşlandığı nar ekşili ve sumaklı sebze bulyonundan'], 'Kars kaz eti geleneğinde haşlanıp fırınlanan kazdan süzülen aromatik yağ ve haşlama suyuyla pişen bulgur pilavı, kaz etinin en ayrılmaz tamamlayıcısıdır.'),
  ('Bolu\'nun Mengen ilçesinin Osmanlı saray mutfağından Cumhuriyet döneminin büyük otel ve kurum mutfaklarına dek \'aşçılar diyarı\' olarak ün kazanmasının temel tarihsel dayanağı nedir?', 'Saray mutfağında (Matbah-ı Âmire) yetişen Mengenli ustaların usta-çırak zinciriyle hemşehrilerini mesleğe kazandırması', ['Türkiye\'deki tüm baharat ve pirinç tarlalarının yalnızca Mengen ovasında devlet eliyle kurulmuş olması', 'Mengen\'de tarım ve hayvancılığın kanunla yasaklanarak halkın zorunlu aşçılık vergisine bağlanması', 'Avrupa\'dan gelen Fransız şeflerin 16. yüzyılda yalnızca Bolu dağlarında mutfak akademisi açması'], 'Osmanlı saray ve konak mutfaklarında uzmanlaşan Mengenli aşçılar, kuşaktan kuşağa aktardıkları lonca ve çıraklık geleneğiyle Türkiye\'de profesyonel aşçılık mesleğinin omurgasını oluşturmuştur.'),
  ('Kayseri mutfağında \'yağlama\' (şebit mantısı) hazırlanırken ince açılıp sacda pişirilen sıcak lavaşların arasına kat kat serilen kıymalı harcın en önemli kıvam özelliği nedir?', 'Domatesli, biberli ve soğanlı kıymanın lavaşları yumuşatacak kadar sulu ve yağlı bırakılması', ['Kıymanın hiç su ve domates katılmadan kuru kavurma gibi kavrulup soğutulması', 'Harç içine bol miktarda un ve nişasta eklenerek katı muhallebi kıvamına getirilmesi', 'Et yerine yalnızca ezilmiş patates, lor peyniri ve kuru nane karışımı sürülmesi'], 'Kayseri yağlamasında 10-12 kat ince şebit ekmeğinin her bir katı önce tenceredeki sulu salçalı-kıymalı harcın yağına batırılır, üst üste dizilip dörde bölünerek sarımsaklı yoğurtla dürüm gibi yenir.'),
  ('Kayseri mantısının geleneksel ustalık ölçütü olarak halk arasında dile getirilen \'bir kaşığa kırk mantı sığması\' sözü yemeğin hangi özelliğini vurgular?', 'Hamurun çok ince açılıp minik kareler halinde sabır ve el maharetiyle sıkılmasını', ['Mantı suyunun içine kırk farklı baharat ve şifalı dağ otunun katılmasını', 'Yemeğin kırk kişilik dev bakır kazanlarda kırk saat boyunca kaynatılmasını', 'Haşlanan hamurların içine et yerine yalnızca minik susam taneleri konulmasını'], 'Kayseri\'de özellikle gelin adaylarının hamaratlığını simgeleyen bu deyim, hamurun kalın kalmadan zar inceliğinde açılması ve içli minik bohçalar halinde kapatılmasındaki inceliği anlatır.'),
  ('Erzurum\'un İspir ilçesiyle özdeşleşen coğrafi işaretli \'İspir kuru fasulyesi\'ni etli güveç yemeklerinde üstün kılan fiziksel pişme özelliği nedir?', 'İnce kabuklu yapısı sayesinde suda bekletilip piştiğinde kabuk atmadan ve dağılmadan tereyağı gibi yumuşaması', ['Çok kalın kabuklu olduğu için üç saat kaynatılsa bile kıtır kalarak çiğ sebze dokusunu koruması', 'Pişme esnasında renginin tamamen siyaha dönerek yemeğe koyu mürekkep görünümü vermesi', 'İçerisinde hiç nişasta bulunmadığı için yemeğin suyunu tamamen duru ve yağsız bırakması'], 'Çoruh Vadisi\'nin mikroikliminde yetişen şeker tipindeki İspir fasulyesi %80\'lere varan su tutma kapasitesiyle irileşir, ince zarı yırtılmaz ve ağızda eriyen kremamsı bir doku sunar.'),
  ('Avrupa Birliği nezdinde Türkiye\'nin tescil ettirdiği ilk coğrafi işaretli ürün olan geleneksel hamur tatlısı hangisidir?', 'Gaziantep baklavası', ['Afyonkarahisar manda kaymaklı ekmek kadayıfı', 'Bursa kestane şekeri ve tahinli pidesi', 'Hatay peynirli künefesi ve taş kadayıfı'], 'Gaziantep baklavası 2013 yılında Avrupa Birliği Komisyonu tarafından tescillenerek Türkiye\'nin AB tescilli ilk coğrafi işaretli gıda ürünü olmuştur.'),
  ('Kare kesilmiş baklava yufkalarının içine buğday unu ve sütle pişirilen irmik kaymağı ile fıstık konulup üçgen muska şeklinde kapatılmasıyla yapılan tatlı hangisidir?', 'Şöbiyet', ['Burma sarılıp kızartılan cevizli saray sarması', 'Nişasta ve gül suyuyla soğutulan su muhallebisi', 'Pekmezli şerbetle fırınlanan tahinli kabak tatlısı'], 'Şöbiyet, çok katlı büyük tepsi baklavasından farklı olarak tek tek kare katmanların arasına süt-irmik kaymağı ve boz fıstık konularak üçgen katlanmasıyla üretilir.'),
  ('Gaziantep\'te özellikle düğün ertesi sabah kahvaltısında ikram edilen, zar gibi açılmış tek kat hamurun kaymak, fıstık ve şekerle katlanıp taş fırında pişirildiği tatlı hangisidir?', 'Antep katmeri', ['Haşhaş ezmesi sürülerek tavada pişirilen Afyon katmeri', 'Şerbetli tel kadayıf arasına basılan peynirli künefe', 'Yumurta ve sütle çırpılıp kızartılan akıtma krep'], 'Şerbet dökülmeden hamurun kendi içindeki toz şeker, koyun kaymağı ve bol boz fıstığın fırın ısısıyla erimesiyle pişen Antep katmeri tescilli bir sabah lezzetidir.'),
  ('Hatay künefesinin iç dolgusunda kullanılan ve ısıyla eriyip metrelerce uzamasına rağmen dağılmayan özel peynirin temel üretim özelliği nedir?', 'Tuzsuz taze künefelik peynir olması', ['Kaya tuzlu salamurada altı ay olgunlaştırılmış sert peynir olması', 'İsli meşe dumanında kurutulmuş baharatlı Çerkez peyniri olması', 'Küflendirilerek deri tulumlara basılmış yağsız çökelek olması'], 'Antakya künefesinde yalnızca günlük mayalanmış, suyu süzülmüş ve hiç tuz katılmamış özel künefelik taze peynir kullanılır.'),
  ('Mersin ve Adana yöresinin coğrafi işaretli enerji tatlısı \'cezerye\'ye hem adını hem de turuncu-kehribar rengini veren ana sebze-meyve hammaddesi nedir?', 'Rendelenip haşlanmış havuç', ['Kireç suyunda bekletilmiş kışlık bal kabağı dilimi', 'Güneşte kurutulmuş tatlı Malatya kayısısı püresi', 'Kabuğu soyulmuş olgun Trabzon hurması ezmesi'], 'Arapça \'cezer\' (havuç) sözcüğünden türeyen cezerye; havucun şeker, zencefil, tarçın ve karanfille kavrulup fıstık veya cevizle kalıplanması ve Hindistan cevizine bulanmasıyla yapılır.'),
  ('Kahramanmaraş dövme dondurmasına çatal-bıçakla kesilebilen sert, esnek ve geç eriyen benzersiz dokusunu kazandıran iki temel yöresel bileşen hangisidir?', 'Ahır Dağı keçi sütü ve yabani salep', ['Pastörize inek kreması ve mısır nişastası şurubu', 'Koyun yoğurdu süzmesi ve kavrulmuş buğday unu', 'Badem sütü özütü ve bitkisel keçiboynuzu zamkı'], 'Kekik ve geven otlarıyla beslenen keçilerin yoğun sütü ile yabani orkide yumrularından elde edilen salep, uzun süre dövüldüğünde Maraş dondurmasının sakızımsı yapısını kurar.'),
  ('Osmanlı saray mutfağında ve Ramazan sofralarında mısır nişastası ile suyun incecik tavada pişirilip kurutulmasıyla elde edilen yaprakların gül sulu sıcak sütle ıslatıldığı tatlı hangisidir?', 'Güllaç', ['Fırında üstü karamelize edilerek yakılan sütlaç', 'Badem unu ve Hindistan ceviziyle pişirilen keşkül', 'Nişasta ve safranla şeffaf dondurulan sarı zerde'], '15. yüzyılda Kastamonulu Ali Usta aracılığıyla saray mutfağına girdiği bilinen \'güllü aş\' (güllaç), mısır nişastalı kuru yaprakların şekerli ve gül sulu ılık sütle buluşturulmasıyla yapılır.'),
  ('Tavukgöğsü veya muhallebi karışımının geniş bakır tepsi tabanına serpilen pudra şekeri üzerinde kontrollü biçimde karamelize edilip rulo sarılmasıyla sunulan tatlı hangisidir?', 'Kazandibi', ['Yumurta sarısıyla taş fırında kızartılan Hamsiköy sütlacı', 'Kızarmış ekmek dilimleriyle şerbetlenen saray ekmeği', 'İrmik ve peynirle fırınlanarak ters çevrilen höşmerim'], 'Bakır tepsi veya kazan tabanındaki şeker ve muhallebi katmanının ocak üzerinde çevrile çevrile yakılmasıyla elde edilen yanık karamel aroması kazandibine adını vermiştir.'),
  ('Düğün, sünnet ve zafer şenliklerinde pilavın yanına veya sonuna ikram edilen \'zerde\' tatlısına parlak altın sarısı rengini ve hoş kokusunu veren baharat hangisidir?', 'Safran', ['Kavrulmuş çemen tohumu ve tatlı kırmızı toz biber', 'Dövülmüş karanfil tomurcuğu ve toz tarçın kabuğu', 'Kurutulmuş menengiç meyvesi ve kakule çekirdeği'], 'Farsça \'zerd\' (sarı) kelimesinden adını alan zerde; pirinç, su, şeker, nişasta, gül suyu ve ıslatılmış safran telleriyle (bazen zerdeçal takviyesiyle) pişirilip kuş üzümü ve çam fıstığıyla süslenir.'),
  ('Hicri takvimin Muharrem ayının onuncu gününden itibaren kaynatılıp komşulara dağıtılan ve bereket ile paylaşmayı simgeleyen çok malzemeli geleneksel Türk tatlısı hangisidir?', 'Aşure', ['Pekmez ve cevizle dondurulan kışlık kesme bulamaç', 'Kuru incir ve sütle mayalanan Ege incir uyutması', 'İrmik ve fıstıkla kavrulan sıcak dondurmalı helva'], 'Buğday, nohut, kuru fasulye, kuru meyveler ve kuruyemişlerin bir arada kaynatılmasıyla hazırlanan aşure, Anadolu\'da komşuluk hukukunun ve kültürel birlikteliğin en güçlü simgesidir.'),
  ('Balıkesir, Çanakkale ve Tekirdağ hattında yeni sağılmış çiğ sütten mayalanan tuzsuz taze peynirin (teleme) irmik ve şekerle pişirilmesiyle üretilen sarı renkli peynir tatlısı Balıkesir\'de hangi adla tescillidir?', 'Höşmerim', ['Süzme yoğurt ve yumurtayla fırınlanan lor tatlısı', 'Tuzlu tulum peyniri ve mısır unuyla yapılan kuymak', 'Tuzsuz peynir ve tel kadayıfla kızartılan künefe'], 'Orta Asya\'dan Yörük göçleriyle Batı Anadolu\'ya taşınan Balıkesir höşmerimi; tuzsuz taze peynir telemesi, irmik, şeker ve yumurta sarısıyla kavrularak hazırlanır.'),
  ('Afyonkarahisar mutfağının simgesi olan \'ekmek kadayıfı\' şerbetlenirken altının yanmaması ve içinin sünger gibi kabarıp şerbeti eşit çekmesi için geleneksel olarak bazen hangi meyveyle koyu kırmızı versiyonu da hazırlanır?', 'Ekşi vişne', ['Fırınlanmış tatlı bal kabağı ve havuç püresi', 'Kurutulmuş sarı kayısı ve beyaz dut özütü', 'Kabuğu soyulmuş yeşil elma ve armut dilimi'], 'Kurutulmuş özel yassı ekmek kadayıfı ılık suda büyütüldükten sonra karamelize şeker şerbetiyle veya vişneli ekmek kadayıfı olarak pişirilip üzerinde kalın Afyon manda kaymağıyla servis edilir.'),
  ('Artvin, Rize ve Hopa kıyı şeridinde ev yapımı ince baklava yufkalarının arasına karabiberli tatlı muhallebi ve şerbet konularak fırınlanan coğrafi işaretli tatlı hangisidir?', 'Laz böreği', ['Mısır unu ve karalahanayla yapılan çerkez böreği', 'Kıyma ve pudra şekeriyle kızartılan küt böreği', 'Tuzsuz lor peyniri ve tarçınla sarılan kol böreği'], 'Adında \'börek\' geçmesine rağmen şerbetli ve muhallebili bir tatlı olan Hopa/Doğu Karadeniz Laz böreğinde, muhallebinin içine yumurta kokusunu kesip aromayı derinleştiren az miktarda taze çekilmiş karabiber katılır.'),
  ('İzmir\'in hayır ve sokak kültürünün parçası olan \'İzmir lokması\'nı ortası delik halka lokmadan farklı olarak bir de avuç sıkımıyla küre biçiminde yapılan küçük çeşidi hangi adla bilinir?', 'Saray lokması', ['Yumurta ve irmikle kalıptan sıkılan tulumba tatlısı', 'Haşhaşlı hamurun bükülmesiyle yapılan nokul çöreği', 'Peynirli hamurun şerbetlenmesiyle sunulan kalburabastı'], 'Ege\'de mevlit, hayır ve kandillerde sokakta ücretsiz dağıtılan lokmanın ortası delik yassı çeşidine İzmir lokması, fındık/ceviz büyüklüğünde yuvarlak dökülen çeşidine ise saray lokması denir.'),
  ('Manisa\'da Yavuz Sultan Selim\'in eşi Ayşe Hafsa Sultan\'ın iyileşmesi üzerine Merkez Efendi tarafından halka saçılmasıyla 500 yıllık şenliğe dönüşen 41 baharatlı şifalı şekerleme hangisidir?', 'Mesir macunu', ['Kavanozda saklanan bergamot aromalı akide şekeri', 'Nişasta ve gülyağıyla kestirilen çifte kavrulmuş lokum', 'Elma şırası ve tarçınla dondurulan elma şekeri'], 'UNESCO Somut Olmayan Kültürel Miras Listesi\'nde yer alan Manisa Mesir Macunu Festivali\'nde, Sultan Camii kubbe ve minarelerinden halka kağıtlara sarılı baharatlı mesir macunları saçılır.'),
  ('Anadolu\'da doğum, ölüm, sünnet, askere uğurlama ve kandil gibi toplumsal geçiş anlarında kavrulup komşulara dağıtılan \'un helvası\' veya \'irmik helvası\' geleneği kültürel olarak neyi ifade eder?', 'Acıyı ve sevinci komşularla paylaşıp hayır duası alma dayanışmasını', ['Evdeki fazla un ve şeker stoklarını vergi memurlarından gizleme çabasını', 'Yalnızca saray aşçılarının yılda bir kez uygulayabildiği lonca sınavını', 'Misafirlere yemeğin bittiğini ve hemen kalkmaları gerektiğini bildirmeyi'], 'Türk kültüründe \'ölünün helvasını kavurmak\'tan kandil helvasına uzanan gelenek, kokunun mahallede yayılmasıyla birlikte komşular arası duygudaşlık ve paylaşım bağını canlı tutar.'),
  ('Erzurum mutfağında Ramazan aylarının simgesi olan \'kadayıf dolması\' hazırlanırken tel kadayıfa sarılmış cevizli rulolar kızgın yağa atılmadan önce hangi karışıma batırılır?', 'Çırpılmış yumurta', ['Sarımsaklı yoğurt ve mısır nişastası bulamacı', 'Pekmezli su ve kavrulmuş susam taneleri', 'Eritilmiş tereyağı ve toz Antep fıstığı ezmesi'], 'Taze tel kadayıfın içine iri ceviz içi konulup sıkıca sarıldıktan sonra çırpılmış yumurtaya bulanarak kızartılan ve soğuk şerbete atılan kadayıf dolması Erzurum adına tescillidir.'),
  ('Sakarya, Düzce ve Hatay mutfaklarında kışlık bal kabağı tatlısı pişirilirken dilimlerin üzerine toz şeker serpilip su eklenmeden bir gece bekletilmesinin mutfak bilimi açısından yararı nedir?', 'Ozmozla kabağın kendi öz suyunu salıp lezzetini seyreltmeden pişmesini sağlamak', ['Kabak dilimlerinin içindeki tüm doğal şekeri dışarı atıp kalorisini sıfırlamak', 'Sebzenin turuncu karoten pigmentlerini parçalayarak beyaz renk almasını sağlamak', 'Şekerin kabak liflerini dondurarak fırında hiç yumuşamadan sert kalmasını sağlamak'], 'Dışarıdan musluk suyu eklendiğinde kabak tatlısının aroması yavanlaşır; akşamdan şekere yatırılan bal kabağı kendi hücre suyunu bırakır ve bu yoğun şurupta lokum gibi pişip tahin-cevizle sunulur.'),
  ('Adapazarı (Sakarya) yöresinde iri gri-beyaz kabuklu kestane kabağından yapılan kabak tatlısının servisinde üzerine cömertçe gezdirilen geleneksel ikili hangisidir?', 'Susam tahini ve dövülmüş ceviz içi', ['Ekşi nar ekşisi ve kavrulmuş tuzlu kabak çekirdeği', 'Sarımsaklı süzme yoğurt ve kırmızı biberli tereyağı', 'Gül suyu şurubu ve rendelenmiş taze limon kabuğu'], 'İç dokusu sıkı ve az lifli olan Adapazarı beyaz kestane kabağı fırınlanıp karamelize edildikten sonra geleneksel olarak tahin, manda kaymağı ve bol cevizle ikram edilir.'),
  ('Osmanlı sarayından günümüze ulaşan ve haşlanmış hamurun yıldız uçlu torba veya kalıptan doğrudan ılık/soğuk yağa sıkılıp kabartılarak kızartıldığı, ardından koyu soğuk şerbete atıldığı tatlı hangisidir?', 'Tulumba tatlısı', ['Sıcak şerbetle yumuşatılan süngerimsi revani kek', 'Cevizli hamurun rendeye bastırıldığı kalburabastı', 'Haşhaş ve irmikle tepsiye yayılan şekerpare'], 'Su, yağ ve unun tencerede pişirilmesiyle yapılan \'pataşu\' benzeri hamura yumurta ve az irmik-nişasta yedirilip oluklu tulumba kalıbından yağa sıkılmasıyla çıtır tulumba tatlısı elde edilir.'),
  ('Geleneksel Türk mutfağında şerbetli hamur tatlıları (baklava, şekerpare, kalburabastı) hazırlanırken tatlının hamurlaşmaması için şerbet ve tatlı sıcaklığı konusunda uygulanan temel kural nedir?', 'Biri sıcakken diğerinin ılık veya soğuk olması', ['Hem tatlının hem şerbetin fokurdayan kaynar halde birleştirilmesi', 'Her ikisinin de buzdolabında bir gün soğutulduktan sonra dökülmesi', 'Şerbetin hiç kaynatılmadan çiğ şekerli su olarak fırına sürülmesi'], 'Ekmek kadayıfı gibi istisnalar dışında çıtır ve kıyır hamur tatlılarında ikisi birden kaynar olursa hamur haşlanıp lapalaşır; ikisi birden soğuk olursa tatlı şerbeti içine çekemez.'),
  ('Cevizli hamur bezelerinin üzerinin petekli, oluklu veya delikli bir mutfak gereci üzerinde bastırılıp kapatılmasıyla karakteristik desenini alan şerbetli ev tatlısı hangisidir?', 'Kalburabastı', ['Üzerine bütün fındık veya badem saplanan şekerpare', 'Portakal kabuğu ve havuçla pişirilen cezerye dilimi', 'Yufka şeritlerinin gül biçiminde sarıldığı bülbülyuvası'], 'Geçmişte tahıl elemekte kullanılan geniş gözenekli \'kalbur\' yüzeyine hamurun bastırılıp cevizle rulo kapatılmasından dolayı tatlıya kalburabastı adı verilmiştir.'),
  ('Afyonkarahisar\'ın \'kaymaklı lokum\' (Afyon lokumu) çeşidinde ince açılan beyaz lokum tabakasının arasına rulo yapılmadan önce hangi yöresel ürün sürülür?', 'Manda kaymağı', ['Sürtme sarı haşhaş ezmesi ve ceviz', 'Ekşi vişne marmeladı ve tarçın', 'Çifte kavrulmuş Bozkır susam tahini'], 'Günlük taze tüketilen meşhur Afyon kaymaklı lokumunda, Hindistan cevizli tepsiye yayılan ince yumuşak lokum tabakasının içine taze manda kaymağı döşenip rulo halinde sarılır.'),
  ('Muğla\'nın Bodrum ve Datça kıyıları ile İzmir Çeşme\'de muhallebi, sütlaç, dondurma ve kurabiyelere eşsiz çamsı-reçineli koku veren \'damla sakızı\' hangi ağaçtan elde edilir?', 'Sakız ağacı (Pistacia lentiscus) gövde çiziklerinden sızan reçineden', ['Kızılçam kozalaklarının kaynatılıp dondurulan öz suyundan', 'Sığla (günlük) ağacının yapraklarından damıtılan uçucu yağdan', 'Yabani badem ağacının kabuğunda oluşan tatlı zamk topaklarından'], 'Antep fıstığı ve menengiçle aynı familyadan olan sakız ağacının (Pistacia lentiscus var. chia) gövdesi çizildiğinde damla damla akan ve havada katılaşan aromatik reçine damla sakızıdır.'),
  ('Giresun mutfağında ve fındık üretim kuşağında kavrulmuş Giresun kalite tombul fındıklarının şekerle ezilmesiyle yapılan, yüksek enerji veren coğrafi işaretli sürülebilir tatlı hangisidir?', 'Giresun fındık ezmesi', ['Mısır unu ve sütle pişirilen karalahana diblesi', 'Üzüm şırası ve unla kurutulan dut pestili', 'Tereyağı ve peynirle kavrulan yayla kuymağı'], 'Yağ ve aroması en yüksek fındık çeşidi kabul edilen Giresun tombul fındığının kavrulup yüksek oranda şekerle taş değirmen/ezicilerde pürüzsüz hale getirilmesiyle coğrafi işaretli fındık ezmesi üretilir.'),
  ('Gaziantep baklavasının büyük yuvarlak tepside merkezden dışa doğru geniş üçgenler halinde kesilen, kaymak ve dondurmayla sunuma en uygun coğrafi işaretli kesim çeşidine ne ad verilir?', 'Havuç dilimi', ['Kare bohça şeklinde kapatılan kaymaklı şöbiyet', 'Oklavaya büzülerek sarılan cevizli burma tatlısı', 'Ortasında fıstık çukuru bulunan bülbülyuvası'], 'Büyük yuvarlak bakır tepsinin merkezinden kenarlara doğru dilimlenmesiyle her bir parçanın şekli havucu andırdığı için bu iri ve bol fıstıklı çeşide havuç dilimi baklava denir.'),
  ('Sivas, Erzincan ve Gümüşhane mutfaklarında ince açılan baklava yufkalarının oklavaya sarılıp iki uçtan ortaya doğru büzüştürülmesiyle kırışık rulo görünümü verilen cevizli şerbetli tatlı hangisidir?', 'Sarıburma', ['Kâsede safran ve pirinçle soğutulan düğün zerdesi', 'İrmik ve sütle pişirilip ters çevrilen prenses tacı', 'Kızarmış ekmek üstüne krema dökülen Kıbrıs tatlısı'], 'Anadolu\'nun pek çok ilinde bayram tepsilerinin baş tacı olan sarıburma (Gümüşhane\'de burma, Elazığ\'da dolanger), yufkanın oklavada büzülmesi sayesinde şerbeti katmanlarında dengeli tutar.'),
  ('Bursa mutfağında süt, şeker, yumurta ve mayayla tutulan poğaça benzeri yumuşak hamurun yuvarlak açılıp ortasına bol susam tahini ve şeker dökülerek taş fırında pişirildiği coğrafi işaretli lezzet hangisidir?', 'Bursa tahinli pidesi', ['Kıyma ve domatesle ince uzun açılan Konya etli ekmeği', 'Kavrulan mısır unu ve peynirle yapılan Trabzon kuymağı', 'Nohut mayası ve sosisle hazırlanan Çeşme kumrusu'], 'Bursa\'da yerli halkın kısaca \'tahinli\' dediği ve hem sabah kahvaltısında hem tatlı niyetine ılık tükettiği tahinli pide, pamuk gibi mayalı kenarları ve ortasındaki karamelize tahin havuzuyla ünlüdür.'),
  ('Isparta ve Burdur yöresinde süzme yoğurt, yumurta, irmik ve unla çırpılan harcın fırınlanıp şerbetlenmesiyle yapılan ve hiç yağ içermemesine rağmen sünger gibi kabaran geleneksel tatlı hangisidir?', 'Yoğurt tatlısı', ['Kat kat tereyağlı yufkayla açılan fıstıklı saray baklavası', 'Susam tahini ve çöven köküyle yoğrulan cevizli yaz helvası', 'Kızgın sıvı yağda kızartılıp şerbete atılan lokma tatlısı'], 'Ege ve Göller Yöresi ev mutfağında çok sevilen yoğurt tatlısı (sünger tatlısı / şambali akrabası), yoğurdun asitliğiyle karbonatın tepkimeye girmesi sayesinde yağsız olduğu halde çok hafif kabarır.'),
  ('Kars, Ardahan ve Erzurum yaylalarında arıların binlerce yüksek irtifa kır çiçeğinden topladığı nektarla ürettiği, düşük nem oranı ve zengin polen çeşitliliğiyle tescillenen doğal tatlı ürün hangisidir?', 'Kars çiçek balı ve Anzer (Rize) balı', ['Muğla ve Marmaris kızılçam ormanlarından sağılan salgı çam balı', 'Şeker pancarı küspesinin kazanlarda kaynatılmasıyla yapılan pekmez', 'Keçiboynuzu baklalarının sıcak suda özütlenmesiyle üretilen harnup özü'], 'Kafkas arı ırkıyla üretilen Kars balı ve endemik çiçek florasıyla ünlü Rize İkizdere Anzer yaylası balı, ağaç salgısından değil yüksek rakım çayır çiçeklerinin nektarından elde edilen çiçek ballarıdır.'),
  ('İrmik helvası kavrulurken irmiğin yanmadan kehribar rengi alması ve tane tane açılması için tereyağıyla birlikte tencerenin en başında irmiğe ne eklenerek birlikte kavrulur?', 'Dolmalık çam fıstığı', ['Rendelenmiş Hindistan cevizi ve pudra şekeri', 'Toz tarçın kabuğu ve kuru kuş üzümü taneleri', 'Sıcak süt kaymağı ve vanilya özütü damlaları'], 'Geleneksel irmik helvasında çam fıstığı irmikle aynı anda yağa atılır; fıstıkların pembeleşmeye başlaması irmiğin de tam kıvamında kavrulduğunun görsel göstergesi olarak kullanılır.'),
  ('Dondurmalı irmik helvası servis edilirken helvanın sıcak veya ılık, içindeki Maraş dondurmasının ise sert ve soğuk olması damakta nasıl bir gastronomi deneyimi yaratır?', 'Sıcak-soğuk ve taneli-kremsi doku karşıtlığı', ['Tuzlu-ekşi ve acı-buruk baharat dengesi', 'Mayalı-gazlı ve fermente asidik içim serinliği', 'Kıtır-kurutulmuş ve tütsülü etsi koku yoğunluğu'], 'Sıcak kavruk irmiğin aroması ile geç eriyen soğuk keçi sütlü Maraş dondurmasının birleşimi, Türk tatlı sunumlarında sıcaklık ve doku kontrastının en başarılı örneklerinden biridir.'),
  ('İstanbul ve saray pastacılık geleneğinde acı badem ve tatlı badem ununun yalnızca toz şeker ve yumurta akıyla tahta kaşıkla pişirilip mermer tezgahta soğutulduktan sonra fırınlandığı çatlak yüzeyli klasik kurabiye hangisidir?', 'Acıbadem kurabiyesi', ['Tereyağı ve pudra şekeriyle kavrulan un kurabiyesi', 'Tahin ve pekmezle yoğrulan susamlı anne kurabiyesi', 'Mahlep ve çörek otuyla fırınlanan tuzlu kandil simidi'], 'Hiç buğday unu ve katı yağ içermeyen geleneksel acıbadem kurabiyesi; badem unu, şeker ve yumurta akının bakır tencerede sakızlaşana dek pişirilip iki kurabiye tabanı birbirine yapıştırılarak sunulmasıyla ünlüdür.'),
  ('Kandil gecelerinde pastane ve fırınlarda susamlı veya çörek otlu küçük halkalar halinde üretilen \'kandil simidi\' hamuruna kendine özgü nostaljik ve hoş kokusunu veren baharat tohumu hangisidir?', 'Mahlep', ['Öğütülmüş çemen otu ve acı kırmızı pul biber', 'Kurutulmuş nane yaprağı ve ezilmiş sarımsak tozu', 'Tane karabiber, kimyon ve kurutulmuş kekik'], 'Yabani kiraz (idris ağacı / Prunus mahaleb) çekirdeklerinin iç tohumlarının öğütülmesiyle elde edilen mahlep, kandil simidi ve paskalya çöreği gibi geleneksel İstanbul hamur işlerinin imza aromasıdır.'),
  ('Bolu\'nun Mudurnu ilçesiyle özdeşleşen \'Mudurnu saray helvası\' üretiminde tel tel açılan helvanın pişmaniyeye göre daha pürüzsüz ve ağızda eriyen yapıda kalması için kavurma aşamasında hangi yağ kullanılır?', 'Saf tereyağı', ['Soğuk sıkım sızma zeytinyağı ve susam yağı', 'Rafine pamuk çiğidi yağı ve kuyruk yağı', 'Kavrulmuş haşhaş yağı ve fındık küspesi'], 'Mudurnu saray helvası un, tereyağı ve şekerle geleneksel çekme tekniğiyle üretilip kare lokmalar halinde kesilen tescilli bir Batı Karadeniz şekerlemesidir.'),
  ('Bitlis, Van ve Ağrı yaylalarında arıların kovanda kendi ördüğü doğal balmumu peteğiyle (temel suni petek koymadan) sepet veya kütük kovanlarda ürettiği bala ne ad verilir?', 'Karakovan balı', ['Santrifüj makinesinde süzülmüş narenciye çiçek balı', 'Kızılçam ormanlarından toplanan koyu salgı balı', 'Kaynatılmış üzüm şırasıyla çırpılan beyaz çalma pekmez'], 'Özellikle Bitlis Hizan ve Siirt Pervari karakovan balları, dışarıdan hazır mum levha verilmeden arının kendi salgıladığı saf balmumuyla ördüğü sepet kovanlarda üretilmesiyle tescillidir.'),
  ('Osmanlı sokak şekerlemeciliğinde tahta çubuğun ucundaki bölmeli teneke tepside beş-altı farklı meyve ve baharat aromalı yumuşak akışkan şekerin tahta çubuğa dolanarak çocuklara satıldığı geleneksel lezzet hangisidir?', 'Osmanlı macunu', ['Kızgın yağda pişirilen şerbetli halka tatlısı', 'Kağıt külahlarda satılan kavrulmuş sarı leblebi', 'İki ince gofret arasına konulan dondurmalı helva'], 'Limon, portakal, çilek, nane, kivi/bergamot ve tarçın bölmelerinden küçük tahta çubuğa rengârenk sarılarak limon sürülüp sunulan macun şekeri, panayır ve Ramazan eğlencelerinin simgesidir.'),
  ('İnce açılmış baklava yufkasının ortası boş halka şeklinde büzülüp fırınlandıktan sonra şerbetlendiği ve ortadaki yuvasına bol bütün Antep fıstığı veya ceviz doldurulduğu klasik Türk tatlısı hangisidir?', 'Bülbülyuvası', ['Kare kesilip içine kaymak kapatılan üçgen şöbiyet', 'İrmik ve yoğurtla tepside pişirilen düz şambali', 'Süt ve güllaç yaprağıyla soğuk sarılan güllaç rulosu'], 'Görünümü kuş yuvasını, ortasındaki fıstıklar ise yumurtaları andırdığı için bülbülyuvası adını alan bu şerbetli tatlı, Türk baklavacılık sanatının estetik şekillendirme örneklerindendir.'),
  ('Muğla\'nın Kavaklıdere ve Yatağan çevresi ile Denizli\'de dövülmüş ceviz içi ve kuru incir/üzümün baharatlarla yoğrulup silindir şeklinde sarılarak dilimlenen pişirilmeyen doğal kış tatlısına ne ad verilir?', 'İncir sarması', ['Yumurta ve unla kızgın yağda pişirilen tulumba tatlısı', 'Tuzsuz taze peynir ve kadayıfla fırınlanan künefe', 'Pirinç ve safranla kaynatılan şeffaf düğün zerdesi'], 'Ege\'nin en besleyici doğal şekerlemelerinden olan cevizli incir sarması (veya üzüm ezmesi), şeker ilavesiz olarak etli kuru incirlerin çekilip cevizle rulo yapılmasına dayanır.'),
  ('Geleneksel Türk mutfağında etli, soğanlı veya balık yemeklerinin ardından helva ya da şerbetli/sütlü tatlı yenmesinin beslenme alışkanlığı bakımından tarihsel açıklaması nedir?', 'Ağızdaki keskin kokuyu giderip kan şekerini dengeleyerek sofrayı tatlıyla mühürlemek', ['Tatlı yedikten hemen sonra üzerine tekrar sıcak çorba ve kebap servisine başlamak', 'Midedeki tüm sindirim enzimlerini durdurarak yiyeceklerin üç gün sindirilmemesini sağlamak', 'Tuzlu yemeklerde kullanılan baharatların acılığını iki katına çıkarıp susuzluk yaratmak'], '\'Tatlı yiyelim tatlı konuşalım\' anlayışıyla bütünleşen yemek sonu tatlısı (özellikle balık sonrası tahin helvası), hem ağız tadını tazeler hem de misafire ikramın tamamlandığını zarafetle hissettirir.'),
  ('Antakya kömbesine şekil vermek ve üzerindeki geleneksel geometrik/çiçek kabartma desenlerini oluşturmak için kullanılan oyma ahşap gerece ne ad verilir?', 'Kömbe kalıbı', ['Bakır lenger tepsisi ve delikli kevgir kaşığı', 'Mermer havan eli ve çift saplı kebap zırhı', 'Şimşir çorba kepçesi ve ince baklava oklavası'], 'Ceviz, şimşir veya gürgen ağacından elde oyulan kömbe kalıbına susamlı hamur bastırılıp ters vurularak çıkarılır; bu desenler her fırında veya ailede kuşaktan kuşağa aktarılır.'),
  ('Bursa\'da Osmanlı döneminden bu yana süt, pirinç unu, şeker ve damla sakızıyla pişirilen muhallebinin üzerine gül suyu ve şerbet gezdirilmesine benzer biçimde, İstanbul\'da haşlanmış tavuksuz pirinç unu ve nişastayla kâsede dondurup gül suyu-pudra şekeriyle küp kesilen yaz tatlısı hangisidir?', 'Su muhallebisi', ['Tepsi tabanında şekeri yakılarak rulo sarılan kazandibi', 'Fırında yumurta sarısıyla kızartılan pirinçli sütlaç', 'İrmik ve tuzsuz peynirle sıcak kavrulan höşmerim'], 'Yarı süt yarı su ile mısır ve buğday nişastası kaynatılarak tepsiye dökülen, soğuyunca küp kesilip üzerine gül suyu ve pudra şekeri (veya pekmez) serpilen su muhallebisi İstanbul muhallebicilerinin klasik yaz tatlısıdır.'),
  ('Geleneksel aşure pişirilirken kuru fasulye ve nohudun yanı sıra aşureye berrak yerine kremamsı ve bağlayıcı kıvamını veren ana tahıl bileşeni nedir?', 'Kabuğu soyulmuş aşurelik buğday', ['Kavrulmuş ince köftelik esmer bulgur ve kepek', 'Kırık mısır unu ve haşlanmış arpa şehriye', 'Tam çavdar tanesi ve kavuzlu kılçıklı yulaf'], 'Bir gece önceden ıslatılıp nişastasını suya salana dek kaynatılan aşurelik buğday (dövme), dışarıdan un katmaya gerek kalmadan aşurenin tüm tanelerini bir arada tutan helme kıvamını üretir.'),
  ('Van, Bitlis ve Siirt yörelerinin simgesi olan \'Van otlu peyniri\' ilkbaharda koyun sütüyle mayalanırken içerisine katılan ve yaban sarımsağı aroması taşıyan en temel endemik yayla otları hangileridir?', 'Sirmo, mendo ve heliz', ['Deniz börülcesi, şevketibostan ve radika', 'Semizotu, ebegümeci ve taze enginar yaprağı', 'Madımak, ıspanak kökü ve tarla sarmaşığı'], 'Van otlu peynirine hem keskin aromasını hem de doğal antimikrobiyal dayanıklılığını veren başlıca yayla bitkileri Allium cinsinden yabani sarımsak olan \'sirmo\' ile \'mendo\', \'heliz\' (çaşır otu) ve kekiktir.'),
  ('Balıkesir (Susurluk, Manyas, Gönen) ve Bursa (Karacabey, Mustafakemalpaşa) hattında yaklaşık iki yüz elli yıldır üretilen, iri gözenekli, sert ve tuzlu yapısıyla tost ile kahvaltılarda aranan tescilli peynir hangisidir?', 'Mihalıç (Kelle) peyniri', ['Kars çeçil (tel) peyniri', 'Hatay sünme künefe peyniri', 'Düzce isli Abaza peyniri'], 'Adını Karacabey\'in eski adı olan Mihalıç\'tan alan Mihalıç (kelle) peyniri; 3-4 milimetrelik yuvarlak gözenekleri, sert kabuğu ve ızgara ya da Susurluk tostunda erirken kızaran karakteristik dokusuyla ünlüdür.'),
  ('Düzce, Sakarya ve Bolu çevresinde Kafkas göçmeni toplulukların yaşattığı \'isli Çerkez peyniri\' üretilirken peynir sepetleri hangi işlemden geçirilerek açık kahverengi kabuk ve tütsü kokusu kazanır?', 'Meşe veya gürgen odunu dumanının yükseldiği özel tütsü fırınlarında kurutularak', ['Kavrulmuş arpa unu ve pekmezli suya batırılıp taş fırında kızartılarak', 'Kuru çay posası ve ceviz kabuğu kaynatılmış salamura kazanında haşlanarak', 'Siyah zeytin yaprağı ve kömür tozu arasına gömülüp bir ay bekletilerek'], 'Kaynayan süte ekşi peynir altı suyu (şirden yerine asidik kesim) katılarak sepetlerde şekillendirilen Çerkez peyniri, gürgen ya da meşe talaşı dumanında tütsülendiğinde hem dayanıklılığı artar hem de isli bir lezzet alır.'),
  ('Erzurum ve Kars mutfağında yağı alınmış inek sütünün asitliği yükseltilip ısıtılırken tahta sopalarla karıştırılıp askılara asılmasıyla iplik iplik uzayan, yağsız ve lifli peynir hangisidir?', 'Civil (Çeçil) peyniri', ['Ezine beyaz peyniri', 'Kıbrıs hellim peyniri', 'Manyas sepet loru'], 'Coğrafi işaretli Erzurum civil peyniri yağsız sütten tel tel çekilerek üretilir; tek başına tüketildiği gibi lor/çökelekle birlikte bidona basılıp doğal yeşillenmeye bırakılarak \'göğermiş peynir\' yapımında da kullanılır.'),
  ('Diyarbakır ve Karacadağ yöresinde ilkbaharda koyun sütünden elde edilen telemenin sıcak suda haşlanıp yoğrularak saç örgüsü biçiminde büküldüğü coğrafi işaretli peynir hangisidir?', 'Diyarbakır örgü peyniri', ['Balıkesir kelle peyniri', 'Karaman obruk tulumu', 'Bolu keş peyniri'], 'Karacadağ yaylalarında otlayan koyunların sütünden üretilen Diyarbakır örgü peyniri, telemenin 75-80 derece sıcak suda esnetilip üçlü saç örgüsü şeklinde örülmesi ve salamurada saklanmasıyla yapılır.'),
  ('Ayvalık, Bergama ve Manyas çevresinde tatlımsı, tuzsuz ve sürülebilir dokusuyla kahvaltıda karadut veya vişne reçeliyle birlikte yenilen \'lor peyniri\', kaşar veya mihalıç üretiminin hangi yan ürününden elde edilir?', 'Peynir telemesi alındıktan sonra geriye kalan peynir altı suyunun kaynatılıp kestirilmesinden', ['Sütün üzerinde biriken kalın kaymak tabakasının soğuk suyla yayıkta çalkalanmasından', 'Süzme yoğurdun bez torbalarda kaya tuzuyla karıştırılıp güneşte kurutulmasından', 'Çiğ sütün santrifüj makinesinden geçirilerek dibe çöken tortusunun dondurulmasından'], 'Süt kazeini peynire dönüştükten sonra peynir altı suyunda kalan albümin ve globülin (serum) proteinleri 85-90 derecede ısıyla çöktürülerek besin değeri çok yüksek, taze ve hafif lor peyniri üretilir.'),
  ('Trabzon\'un Tonya ve Vakfıkebir ilçeleriyle özdeşleşen coğrafi işaretli yayla tereyağına doğal sarı rengini veren temel unsur aşağıdakilerden hangisidir?', 'Hayvanların yayla meralarındaki sarı çiçekli otlardan aldığı beta-karoten pigmentinin süt yağına geçmesi', ['Yayık çalkalanırken kremanın içine safran şerbeti ve zerdeçal tozunun eklenmesi', 'Tereyağının mısır unuyla birlikte bakır tavada kavrulduktan sonra kalıplanması', 'Sütün kaynatıldığı kazanların iç yüzeyinin sarı pirinç madeniyle kaplanmış olması'], 'İlkbahar ve yaz aylarında Doğu Karadeniz yaylalarında taze yeşil ot ve çiçeklerle beslenen Jersey ve yerli ırk ineklerin sütünde doğal beta-karoten yükselir; bu da tereyağına katkı maddesiz altın sarısı rengini verir.'),
  ('Kuzey Ege\'de (Ayvalık, Gömeç, Burhaniye, Edremit) üretilen coğrafi işaretli zeytinyağlarının dengeli, hafif meyvemsi ve akıcı karakterini belirleyen bölgeye hâkim zeytin çeşidi hangisidir?', 'Ayvalık (Edremit yağlık) çeşidi', ['İri etli Akhisar Domat sofralık çeşidi', 'Küçük çekirdekli Hatay Halhalı çeşidi', 'İnce kabuklu Tarsus Sarıulak çeşidi'], 'Kuzey Ege kıyı kuşağının Kazdağları ve Madra Dağı rüzgârlarıyla beslenen zeytinliklerinde %24\'e varan yüksek yağ oranıyla \'Ayvalık (Edremit)\' çeşidi hâkimdir ve taze çimen-çağla kokulu sızma yağlar verir.'),
  ('Bursa\'nın Mudanya (Trilye), Gemlik ve İznik kıyılarında yetiştirilen coğrafi işaretli \'Gemlik zeytini\' Türkiye sofralarında en çok hangi ürün tipiyle tanınır?', 'İnce kabuklu, küçük çekirdekli ve etli yapısıyla doğal salamura siyah sofralık zeytin olarak', ['Çekirdeği çıkarılıp içine havuç ve badem doldurulan iri yeşil kokteyl zeytini olarak', 'Dalında mantar etkisiyle kendiliğinden tatlanan tuzsuz kahverengi hurma zeytini olarak', 'Yalnızca sabun ve sanayi yağı üretiminde değerlendirilen düşük etli yabani deliceler olarak'], 'Etin çekirdeğe oranı çok yüksek, kabuğu zar gibi ince olan Gemlik (Trilye) zeytini; hem yağ oranı yüksek hem de Türkiye\'nin en makbul siyah sofralık ve sele zeytini çeşididir.'),
  ('Zeytinyağının ev ortamında meyvemsi aromasını ve besin değerini kaybetmeden saklanabilmesi için aşağıdaki depolama koşullarından hangisinden kesinlikle kaçınılmalıdır?', 'Şeffaf cam veya pet şişede ocak yanındaki güneş gören aydınlık tezgâhta bekletmekten', ['Koyu renkli cam şişede veya paslanmaz çelik kapta serin kilerde tutmaktan', 'Şişenin ağzını her kullanımdan sonra hava almayacak biçimde sıkıca kapatmaktan', 'Büyük tenekedeki yağı sık açıp kapamamak için küçük koyu şişelere aktarmaktan'], 'Zeytinyağının dört büyük düşmanı ışık, ısı, oksijen ve nemdir; klorofil pigmentleri ışık gördüğünde fotooksidasyonu hızlandırarak yağı hızla bayatlatır ve ransit (bozuk yağ) kokusu oluşturur.'),
  ('Afyonkarahisar, Uşak, Kütahya ve Eskişehir\'i kapsayan İç Ege kuşağında çörek, bükme ve lokul gibi hamur işlerinin katmanları arasına tereyağı yerine cömertçe sürülen kavruk aromalı yerel ezme/yağ hangisidir?', 'Sarı haşhaş ezmesi ve haşhaş yağı', ['Tuzlu hamsi salamurası ve balık yağı', 'Kurutulmuş nane tozu ve kuyruk yağı', 'Acı biber salçası ve pamuk çiğidi yağı'], 'Haşhaş tarımının merkezi olan Afyonkarahisar ve çevresinde kavrulmuş sarı haşhaş tohumlarının taşta ezilmesiyle elde edilen yağlı haşhaş ezmesi, haşhaşlı çörek, ağzıaçık ve bükmenin temel lezzet vericisidir.'),
  ('Geleneksel Türk mutfağında \'zeytinyağlı yemekler\' (yaprak sarma, taze fasulye, enginar, barbunya pilaki, yer elması) pişirilirken tencereye çok az miktarda toz şeker eklenmesinin mutfak tekniğindeki gerekçesi nedir?', 'Sebze ve domatesin asiditesini dengeleyip soğanların karamelize tatlılığını desteklemek', ['Zeytinyağlı yemeği yemek sonrasına uygun şerbetli bir tatlıya dönüştürmek', 'Zeytinyağının donma noktasını düşürerek buzdolabında kristalleşmesini önlemek', 'Tenceredeki sebzelerin yeşil rengini tamamen kahverengiye boyamak'], 'İstanbul ve Ege zeytinyağlı pişirme üslubunda (soğuk yenen \'pilaki\' ve \'bastı\'larda) bir kesme şeker ölçüsündeki şeker yemeği tatlandırmaz; sebze ve domatesteki ekşiliği yuvarlatarak zeytinyağının aromasını parlatır.'),
  ('Osmanlı ve İstanbul mutfağında kuru fasulye, barbunya veya balık/midye gibi malzemelerin bol soğan, sarımsak, havuç, kereviz, maydanoz ve zeytinyağı ile pişirilip soğuk sunulan yemek grubuna ne ad verilir?', 'Pilaki', ['Yani', 'Borani', 'Kalyeden kavurma'], 'Adını başlangıçta pişirildiği yayvan taş/toprak kaptan (\'plaki\') alan pilaki, İstanbul mutfağında özellikle barbunya, dev fasulye veya palamudun havuç, patates, sarımsak ve zeytinyağıyla pişirilip soğuk yenmesidir.'),
  ('Kastamonu\'nun coğrafi işaretli \'kel simidi\'ni Türkiye\'deki diğer tüm geleneksel simit çeşitlerinden ilk bakışta ayıran görsel ve hazırlık özelliği nedir?', 'Üzerine hiç susam serpilmeden elma veya üzüm pekmezli kaynar kazandan geçirilip taş fırında parlak kızartılması', ['Halka biçiminde değil üçgen muska formunda kapatılıp içine kıyma ve ceviz konulması', 'Hamuruna ıspanak suyu katılarak zümrüt yeşili renkte ve çörek otu kaplı pişirilmesi', 'Fırınlanmak yerine kızgın ayçiçeği yağında pişi gibi kızartılıp pudra şekerine bulanması'], 'Üzerinde tek bir susam tanesi bile bulunmadığı için \'kel simit\' adını alan Kastamonu simidi (ve yakın akrabası Rize simidi), elma pekmezli kaynar suda haşlanıp kara fırında pişirilerek kehribar parlaklığı alır.'),
  ('Anadolu köylerinde sonbaharda imeceyle yüzlerce adet açılıp sac üzerinde pişirilerek üst üste istiflenen, kış boyu yemekten on dakika önce üzerine su serpilip bez altında yumuşatılan ince ekmek hangisidir?', 'Kuru yufka ekmeği', ['Kalın somun francala', 'Yumurtalı Ramazan pidesi', 'Susamlı Çeşme kumrusu'], 'Göçebe ve yerleşik Anadolu mutfağının en akılcı uzun ömürlü ekmek çözümü olan sac yufkası, nemi sıfıra yakın pişirildiği için kuru kilerde aylarca küflenmez; \'yufka sulama/ıslama\' işlemiyle taptaze dürüm olur.'),
  ('Orta Anadolu ve İç Ege\'de mayalı yumuşak hamurun merdaneyle yemek tabağı büyüklüğünde ve bir-iki santimetre kalınlığında açılıp ters çevrilmiş sac veya döküm tava üzerinde iki yüzü çevrilerek pişirilen puf ekmeğe ne denir?', 'Bazlama', ['Galeta', 'Peksimet', 'Fodula'], 'Sıcakken ortadan yarılıp içine taze tereyağı veya tulum peyniri sürülen bazlama, pişerken içindeki buhar basıncıyla balon gibi kabaran yumuşak dokulu geleneksel sac ekmeğidir.'),
  ('Doğu Anadolu\'da (Erzurum, Kars, Van, Ağrı, Iğdır) kahvaltıların ve yolculuk azıklarının baş tacı olan \'içli kete\'nin katmanları arasına konulan geleneksel tuzlu veya hafif tatlı iç harç nedir?', 'Tereyağında altın rengi alana dek kavrulmuş un', ['Haşlanıp ezilmiş barbunya fasulyesi ile ince kıyılmış karalahana karışımı', 'Domates salçası, acı isot biberi ve çiğ kuzu kıymasıyla yoğrulmuş harç', 'Rendelenmiş taze kabak, dereotu ve tuzlu lor peynirinden oluşan sulu iç'], 'Kars ve Erzurum ketesini sıradan çöreklerden ayıran en özgün özellik, mayalı ve tereyağlı hamurun ortasına yerleştirilen kavrulmuş un (\'kete içi / horis\') dolgusu sayesinde haftalarca bayatlamadan kavruk lezzetini korumasıdır.'),
  ('Denizcilerin uzun gemi seferlerinde ve Osmanlı ordusunun sefer menzillerinde aylarca küflenmeden dayanması için iki kez fırınlanarak içindeki nemi tamamen uçurulmuş taş gibi sert ekmeğe ne ad verilirdi?', 'Peksimet', ['Bazlama', 'Akıtma', 'Pişi'], 'İki kez pişirilerek suyundan arındırılan peksimet, küflenmeye karşı son derece dayanıklı olduğu için kalyon mürettebatı ve Yeniçeri sefer kumanyasının en stratejik tahıl erzakıydı; çorba veya suya batırılarak yenirdi.'),
  ('Ramazan aylarında fırınların önünde kuyruklar oluşturan geleneksel \'Ramazan pidesi\'nin fırına sürülmeden önce parmak uçlarıyla üzerine kafes (tırnak) izleri açılıp sulandırılmış un bulamacı sürülmesinin işlevi nedir?', 'Hamurun fırında düzensiz balonlaşmasını önlemek ve parlak kızarmış yumuşak üst kabuk oluşturmak', ['Pidenin içindeki tüm mayayı söndürerek kağıt inceliğinde kuru kraker elde etmek', 'Susam ve çörek otunun hamurun tabanına çökerek taş fırın zeminine yapışmasını sağlamak', 'Pidenin pişme süresini bir saate uzatarak iç dokusunun çiğ kalmasını engellemek'], 'Fırıncıların \'şifa\' adını verdiği ılık unlu su (veya yumurtalı şifa) pide yüzeyindeki nişastayı parlatıp susamı tutar; tırnaklama ise gaz çıkışını dengeler ve dilimlemeyi kolaylaştıran baklava bölmeleri oluşturur.'),
  ('Karadeniz ve Orta Anadolu ev mutfaklarında süt, su, un, tuz ve yumurtayla hazırlanan akışkan krep benzeri bulamacın kızgın sac veya yağlı tavaya kepçeyle dökülerek pişirildiği kahvaltılık hamur işine ne ad verilir?', 'Akıtma (Cızlak / Kaygana)', ['Peksimet (Kuru gevrek)', 'Şebit (Kuru yufka)', 'Halka (Tulumba)'], 'Bölgelere göre Trakya ve Ege\'de akıtma, İç Anadolu ve Batı Karadeniz\'de cızlak, Doğu Karadeniz\'de ise bol yumurtalı ve bazen yeşillikli/hamsili biçimiyle kaygana olarak adlandırılan pratik tava ekmeğidir.'),
  ('İstanbul\'un tarihi pastane ve fırın geleneğinde mahlep, damla sakızı, süt, tereyağı ve yumurtayla yoğrulup üçlü saç örgüsü biçiminde şekillendirilen ve üzerine file badem serpilerek pişirilen yumuşak tatlımsı çörek hangisidir?', 'Paskalya çöreği', ['Tuzlu çatal simidi', 'Susamlı kandil halkası', 'Haşhaşlı Afyon lokulu'], 'İstanbul Rum ve Ermeni fırıncılarından tüm şehir kültürüne mal olan paskalya çöreği, dövülmüş mahlep ve sakızın büyüleyici kokusu ile tel tel ayrılan lifli yumuşak dokusuyla her mevsim pastanelerde üretilir.'),
  ('Geleneksel Anadolu mutfağında bakır tencere, sahan ve kazanların iç yüzeyinin belirli aralıklarla \'kalay\' madeniyle kaplanmasının insan sağlığı açısından zorunlu nedeni nedir?', 'Yiyecek asitlerinin çıplak bakırla tepkimeye girerek zehirli bakır bileşikleri oluşturmasını önlemek', ['Bakır kapların ağırlığını yarı yarıya azaltarak ocak üzerinde daha hızlı ısınmasını sağlamak', 'Tencerenin dış yüzeyini paslanmaz çeliğe dönüştürüp bulaşık makinesine uyumlu hale getirmek', 'Yemeklerin tuz oranını kendiliğinden düşürerek besinlerin daha tatlı pişmesini kolaylaştırmak'], 'Kalaysız (kızarmış) bakır kaplarda domates, yoğurt ve limon gibi asidik gıdalar pişirildiğinde bakır tuzları (bakır çalığı) çözünerek gıda zehirlenmesine yol açar; kalay tabakası güvenli bir koruyucu bariyer oluşturur.'),
  ('Kahvaltıda yumurta, menemen, sucuk veya kuymak gibi yemeklerin hem pişirilip hem de doğrudan içinde sofraya sunulduğu iki kulplu, yayvan ve sığ geleneksel bakır kaba ne denir?', 'Sahan', ['Güğüm', 'Kazan', 'Dibek'], 'Çoğunlukla kubbeli bir kapağa da sahip olan iki kulplu bakır sahan, ısıyı eşit dağıtması ve sıcaklığı sofrada koruması nedeniyle porsiyonluk sıcak ikramların simge gerecidir.'),
  ('Türk hamur işi mutfağında incecik baklava veya börek yufkası açmakta kullanılan \'oklava\' ile kalın poğaça, kurabiye veya bazlama açmakta kullanılan \'merdane\' arasındaki işlevsel fark nedir?', 'İnce uzun oklavanın hamuru kendine sarıp içten dışa esneterek kağıt inceliğine getirmesi, kalın silindir merdanenin ise yukarıdan ağırlıkla bastırması', ['Oklavanın yalnızca paslanmaz çelikten üretilmesi, merdanenin ise her zaman pişmiş topraktan yapılması', 'Merdanenin sıcak sac üzerinde yufka çevirmeye yaraması, oklavanın fırına ekmek sürmekte kullanılması', 'Oklavanın sulu kek çırpmakta tercih edilmesi, merdanenin yalnızca ceviz kırmakta kullanılması'], 'Baklava ve yufka ustalığının sırrı olan uzun ve ince oklava (özellikle şimşir veya gürgen), hamurun katlarını sararak merkezcil el basıncıyla milimetrenin altında inceltmeye olanak tanır.'),
  ('Haşlanan mantı, erişte veya kızartılan lokma gibi taneli yiyecekleri kaynar su ya da kızgın yağ içinden süzerek çıkarmaya yarayan delikli uzun saplı kepçeye ne ad verilir?', 'Kevgir', ['Sahan', 'Cezve', 'Satır'], 'Bakır veya çelik sacın simetrik deliklerle işlenmesiyle yapılan kevgir (daha derin ayaklı süzgeç biçimine Anadolu\'da \'ilistir\' de denir), sıvıyı hızla süzüp katı taneleri zedelemeden almaya yarar.'),
  ('Geleneksel Anadolu ve Osmanlı konak sofralarında yere serilen sofra bezinin üzerine katlanabilir ahşap ayak (\'kasnak / iskemle\') konulduktan sonra üstüne oturtulan büyük yuvarlak metal tepsiye ne denir?', 'Sini', ['Tezgâh', 'Kerevet', 'Ambar'], 'Bakır veya pirinçten dövülen büyük yuvarlak yer sofrası tepsisine sini denir; etrafına bağdaş kurularak oturulur ve tüm aile ortak kâselerden kaşıkla yemek yerdi.'),
  ('Yer sofrasında yemek yenmeden önce ve yendikten sonra evin genç bireylerinin misafirlerin ellerine su dökmek için dolaştırdığı iki parçalı geleneksel temizlik takımı hangisidir?', 'Leğen ve ibrik', ['Güğüm ve kazan', 'Testi ve maşrapa', 'Sahan ve lenger'], 'Ortası sabunluklu ve delikli kapağı kirli suyu gizleyen \'el leğeni\' ile ince uzun emzikli \'ibrik\', geleneksel Türk konukseverliğinde sofrada hijyen ve saygının en zarif simgelerindendir.'),
  ('Tarlaya, dükkâna, yolculuğa veya hasta ziyaretine sıcak ev yemeği taşırken çorba, etli yemek, pilav ve tatlının birbirine karışmadan üst üste kilitlenerek taşındığı katlı metal kaba ne ad verilir?', 'Sefer tası', ['Azık çıkını', 'Su matarası', 'Bakır güğüm'], 'Üç ila beş adet kalaylı bakır veya emaye kap kâsenin üst üste oturup yanlardan metal bir kelepçe kolla sabitlendiği sefer tası, esnaf ve memur öğle yemeği kültürünün nostaljik simgesidir.'),
  ('Buzdolabının evlere girmediği dönemlerde pişmiş yemekleri, peyniri, tereyağını ve eti kedi ya da sineklerden korurken serin hava akımıyla bozulmadan tutmak için kullanılan önü ince metal ağ kaplı ahşap dolaba ne denirdi?', 'Tel dolap', ['Yüklük dolabı', 'Çeyiz sandığı', 'Ekmek teknesi'], 'Kiler, avlu veya kuzeye bakan serin mutfak pencerelerinin önüne asılan tel dolaplar, hava sirkülasyonunu kesmeden haşere ve hayvan girişini önleyen geleneksel gıda muhafaza dolabıdır.'),
  ('Odun sobasının veya ocağın üzerinde sürekli sıcak su bulundurmak, köyden pınar suyu taşımak ve süt sağımında kullanmak amacıyla dar boyunlu, şişkin gövdeli ve kulplu yapılan büyük bakır/alüminyum kaba ne denir?', 'Güğüm', ['Lenger', 'Kevgir', 'Havan'], 'Tabanı geniş olduğu için ateşi iyi alan, boynu daraldığı için buharlaşmayı ve dökülmeyi azaltan kapaklı güğümler, kırsal mutfak ve su/süt taşımacılığının temel demirbaşıdır.'),
  ('Diyarbakır ve Mardin ziyafet mutfağında oğlak veya kuzu sağ kaburgasının cep gibi açılıp içine bademli, yenibaharlı ve karabiberli iç pilav doldurularak dikildiği ve saatlerce buharda/haşlamada pişirildiği yemek hangisidir?', 'Kaburga dolması', ['İskilip bez dolması', 'Şırdan işkembe dolması', 'Tokat kuru bakla dolması'], 'Coğrafi işaretli Diyarbakır kaburga dolmasında karabiber, yenibahar ve reyhanlı bademli pilav kaburga cebine doldurulup pamuk iplikle dikilir; önce kızartılıp sonra tencere içinde süzgeç üzerinde buharda lokumlaşana dek pişirilir.'),
  ('Erzurum\'un Oltu, Tortum ve Olur ilçeleri ile Artvin-Yusufeli hattından yayılan \'cağ kebabı\'nı klasik dikey döner kebabından ayıran en belirgin hazırlık ve pişirme tekniği nedir?', 'Soğan, karabiber ve tuzla dinlendirilen kuzu etinin yatık şişte meşe odunu ateşi önünde çevrilip \'cağ\' adı verilen küçük şişlerle kesilerek alınması', ['Dana kıymasının baharatlarla yoğrulup dikey elektrikli ocakta pişirildikten sonra ince döner bıçağıyla yaprak yaprak sıyrılması', 'Kuzu etinin domates salçası ve yoğurtla kaplanarak kapalı taş fırın tepsisinde kendi suyunda haşlanması', 'Tuzlanmış sığır etinin dikey kuyu tandırına sarkıtılarak duman ve su buharıyla sekiz saat tütsülenmesi'], 'Kıymasız sinirsiz kuzu etinden hazırlanan yatık döner (cağ kebabı) odun ateşinde yatay dönerken yağı üzerine akar; pişen dış katman müşterinin tabağına küçük demir/ahşap şiş (\'cağ\' / \'bico\') geçirilip kesilerek sıcak lavaşla sunulur.'),
  ('Osmanlı saray mutfağı geleneğinden beri Türkiye\'nin en köklü profesyonel aşçı yetiştirme merkezi olarak tanınan ve adına ulusal aşçılık festivali ile gastronomi okulları kurulan Bolu ilçesi hangisidir?', 'Mengen', ['Göynük', 'Gerede', 'Kıbrıscık'], 'Fatih ve II. Mahmud dönemlerinden itibaren saray Matbah-ı Âmire ocaklarında uzmanlaşan Bolu-Mengenli ustalar, kuşaktan kuşağa aktardıkları çıraklık geleneğiyle Türk aşçılığının simge okulu haline gelmiştir.'),
  ('Afyonkarahisar ve İç Anadolu mutfağında yeşil mercimek, ev kesmesi erişte, soğan ve et suyunun bir arada pişirilmesiyle yapılan besleyici kış çorbasına halk arasında hangi esprili ad verilmiştir?', 'Sakala çarpan çorbası', ['Analı kızlı düğün çorbası', 'Kölük aşı bulgur çorbası', 'Dul avrat mercimek çorbası'], 'Kaşığa alındığında uzun ev eriştelerinin sarkan uçları çorbayı içen kişinin çenesine ve sakalına değdiği için Anadolu halk mizahında bu mercimekli erişte çorbasına \'sakala çarpan\' (veya bıyığa takılan) denmiştir.'),
  ('Adana, Hatay ve Mersin mutfaklarında ince bulgur, irmik ve unla yoğrulup serçe parmağı ucuyla çukurlaştırılan düğme biçimli haşlama köftelerin sarımsaklı, domates-biber salçalı ve bol maydanozlu zeytinyağı sosuyla harmanlandığı yemek hangisidir?', 'Fellah köftesi', ['İnegöl ızgara köftesi', 'İzmir sulu fırın köftesi', 'Tekirdağ şiş köftesi'], 'Doğu Akdeniz\'de etsiz de çok lezzetli bir öğün oluşturan fellah köftesi (\'sarımsaklı köfte\' de denir), ortasına parmak basılarak şekillendirildiği için sarımsaklı ekşili salça sosunu bu çukurlarda tutar.'),
  ('Osmanlı saray mutfağında Sultan Abdülaziz döneminde Fransız İmparatoriçesi Eugénie\'nin ziyareti sırasında saray aşçılarının beşamel sos tekniğini közlenmiş patlıcan püresiyle birleştirip üzerine kuzu tas kebabı koyarak yarattığı ünlü klasik yemek hangisidir?', 'Hünkârbeğendi', ['Alinazik kebabı', 'Karnıyarık yemeği', 'Patlıcan musakka'], 'Geleneksel köz patlıcanın un, tereyağı, süt ve kaşar peyniriyle ipeksi bir püre (\'beğendi\') haline getirilip üstüne domatesli yumuşak kuzu eti konulması, geç dönem Osmanlı saray füzyon mutfağının en parlak eseridir.'),
  ('Osmanlı ve geleneksel Türk ev mutfağında bütün bostan veya kemer patlıcanların alacalı soyulup karnı yarıldıktan sonra kıyma yerine bol soğan, sarımsak, domates ve maydanozla zeytinyağlı pişirilip soğuk sunulan klasik yemek hangisidir?', 'İmam bayıldı', ['Karnıyarık', 'Şeyhülmuhşi', 'Tepsi kebabı'], 'Aynı formdaki patlıcan yemeğinin kıymalı ve sıcak yenilen haline \'karnıyarık\', etsiz olarak bol karamelize soğan, sarımsak ve sızma zeytinyağıyla pişirilip ılık/soğuk yenilen haline ise \'imam bayıldı\' denir.'),
  ('Osmanlı saray teşkilatında Topkapı Sarayı\'nın ikinci avlusunda yirmi kubbeli ve yüksek bacalı dev mutfak kompleksine ne ad verilirdi?', 'Matbah-ı Âmire', ['Enderun-ı Hümayun', 'Darphane-i Âmire', 'Tersane-i Âmire'], 'Günde dört-beş bin, divan ve ulufe günlerinde on bini aşkın kişiye yemek çıkaran Topkapı Sarayı mutfakları \'Matbah-ı Âmire\' olarak anılır; içinde Kuşhane, Has Mutfak ve Helvahane gibi uzmanlaşmış bölümler bulunurdu.'),
  ('Gaziantep, Hatay, Afyonkarahisar ve Kayseri illerimizin UNESCO nezdinde ortaklaşa sahip olduğu prestijli uluslararası kültür ağı unvanı aşağıdakilerden hangisidir?', 'UNESCO Yaratıcı Şehirler Ağı - Gastronomi Şehri', ['Avrupa Birliği Organik Tarım Başkenti', 'Dünya Turizm Örgütü Kış Sporları Merkezi', 'Uluslararası Zeytin Konseyi Gen Bankası'], 'Gaziantep (2015), Hatay (2017), Afyonkarahisar (2019) ve Kayseri, köklü mutfak mirasları ve yerel gıda zanaatları sayesinde UNESCO Yaratıcı Şehirler Ağı\'na \'Gastronomi\' dalında kabul edilmiştir.'),
  ('Kayseri mutfağının ünlü \'yağlama\' (şebit mantısı) yemeği hazırlanırken sacda pişirilen ince mayalı şebit lavaşları kat kat üst üste dizilirken her kata ne yayılır?', 'Domatesli, biberli ve bol soğanlı sulu kavrulmuş kıyma harcı', ['Süzme bal, dövülmüş ceviz içi ve eritilmiş manda kaymağı', 'Haşlanmış yeşil mercimek, haşhaş ezmesi ve lor peyniri', 'Közlenmiş patlıcan püresi, tahin ve taze nane yaprakları'], 'On iki ila on beş kat ince şebit ekmeğinin kenarları salçalı-kıymalı harcın sıcak suyuna batırılıp her kata harç serilerek pasta gibi üst üste dizildiği Kayseri yağlaması, dört dilime bölünüp sarımsaklı yoğurtla dürüm yapılarak yenir.'),
  ('Geleneksel Anadolu sofra görgüsünde yemeğe evin en büyüğünün başlamasını beklemek, kendi önünden yemek ve tabakta tek bir pirinç tanesi bile bırakmamak hangi kültürel değer anlayışını yansıtır?', 'Büyüğe saygı, ortak kapta hak gözetme ve nimete şükredip israftan kaçınma bilincini', ['Yemeğin bir an önce bitirilip misafirlerin evden erken ayrılmasını sağlama isteğini', 'Sofradaki yemeklerin tuzsuz veya az pişmiş olduğunu ev sahibine dolaylı yoldan bildirmeyi', 'Kış aylarında bulaşık yıkamak için sıcak su harcanmasını tamamen yasaklama kuralını'], 'Anadolu\'da sofra \'nimet\' ve \'bereket\' makamıdır; büyüğün \'Bismillah / Buyurun\' demesiyle başlanması toplumsal uyumu, herkesin kendi önünden yemesi ortak sini adabını, kırıntı bırakmamak ise emeğe saygıyı simgeler.'),
];
